{"command":"cat > /workspace/src/lz4b.c <<'EOF'
/* LZ4 block format compressor/decompressor - original reimplementation
 * written from knowledge of the LZ4 block format and matching algorithm. */
#include "lz4b.h"
#include <string.h>
#include <stdlib.h>

#define ML_BITS 4
#define ML_MASK ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define MFLIMIT 12
#define LASTLITERALS 5
#define MINLENGTH (MFLIMIT + 1)
#define SKIPTRIGGER 6
#define LIMIT_64K 65547  /* 64KB + MFLIMIT - 1 */
#define KB *(1 << 10)
#define MB *(1 << 20)
#define GB *(1U << 30)

typedef enum { DD_NODICT = 0, DD_PREFIX64K, DD_EXTDICT, DD_DICTCTX } dictDirective_e;
typedef enum { DI_NONE = 0, DI_SMALL } dictIssue_e;
typedef enum { OD_NOTLIMITED = 0, OD_LIMITED = 1 } outputDirective_e;

static inline uint16_t rd16(const void* p) { uint16_t v; memcpy(&v, p, 2); return v; }
static inline uint32_t rd32(const void* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline uint64_t rd64(const void* p) { uint64_t v; memcpy(&v, p, 8); return v; }
static inline void wr16(void* p, uint16_t v) { memcpy(p, &v, 2); }
static inline void wr32(void* p, uint32_t v) { memcpy(p, &v, 4); }

static inline uint32_t hash4(uint32_t seq, lz4b_tabletype tt) {
    if (tt == TT_BYU16) return (seq * 2654435761U) >> (32 - (LZ4B_HASHLOG + 1));
    return (seq * 2654435761U) >> (32 - LZ4B_HASHLOG);
}
static inline uint32_t hash5(uint64_t seq, lz4b_tabletype tt) {
    const uint32_t hashLog = (tt == TT_BYU16) ? LZ4B_HASHLOG + 1 : LZ4B_HASHLOG;
    const uint64_t prime5 = 889523592379ULL;
    return (uint32_t)(((seq << 24) * prime5) >> (64 - hashLog));
}
static inline uint32_t hashPos(const uint8_t* p, lz4b_tabletype tt) {
    if (tt != TT_BYU16) return hash5(rd64(p), tt);
    return hash4(rd32(p), tt);
}
static inline void putIndex(uint32_t idx, uint32_t h, void* table, lz4b_tabletype tt) {
    if (tt == TT_BYU32) { ((uint32_t*)table)[h] = idx; }
    else { ((uint16_t*)table)[h] = (uint16_t)idx; }
}
static inline uint32_t getIndex(uint32_t h, const void* table, lz4b_tabletype tt) {
    if (tt == TT_BYU32) return ((const uint32_t*)table)[h];
    return ((const uint16_t*)table)[h];
}

static inline unsigned ctz64(uint64_t v) { return (unsigned)__builtin_ctzll(v); }

static inline unsigned countMatch(const uint8_t* pIn, const uint8_t* pMatch, const uint8_t* pInLimit) {
    const uint8_t* const pStart = pIn;
    if (pIn < pInLimit - 7) {
        uint64_t d = rd64(pMatch) ^ rd64(pIn);
        if (d) return ctz64(d) >> 3;
        pIn += 8; pMatch += 8;
    }
    while (pIn < pInLimit - 7) {
        uint64_t d = rd64(pMatch) ^ rd64(pIn);
        if (!d) { pIn += 8; pMatch += 8; continue; }
        pIn += ctz64(d) >> 3;
        return (unsigned)(pIn - pStart);
    }
    if ((pIn < pInLimit - 3) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

void lz4b_resetStream(lz4b_stream* s) { memset(s, 0, sizeof(*s)); }
void lz4b_resetStream_fast(lz4b_stream* s) { s->tableType = TT_CLEARED; s->dictionary = NULL; s->dictCtx = NULL; s->dictSize = 0; }

static void prepareTable(lz4b_stream* cctx, int inputSize, lz4b_tabletype tt) {
    if ((lz4b_tabletype)cctx->tableType != TT_CLEARED) {
        if ((lz4b_tabletype)cctx->tableType != tt
            || ((tt == TT_BYU16) && cctx->currentOffset + (unsigned)inputSize >= 0xFFFFU)
            || ((tt == TT_BYU32) && cctx->currentOffset > 1 GB)
            || tt == TT_BYPTR
            || inputSize >= 4 KB) {
            memset(cctx->hashTable, 0, sizeof(cctx->hashTable));
            cctx->currentOffset = 0;
            cctx->tableType = TT_CLEARED;
        }
    }
    if (cctx->currentOffset != 0 && tt == TT_BYU32) cctx->currentOffset += 64 KB;
    cctx->dictCtx = NULL;
    cctx->dictionary = NULL;
    cctx->dictSize = 0;
}

static int compress_generic(lz4b_stream* cctx, const uint8_t* source, uint8_t* dest, int inputSize, int maxOutputSize,
                            outputDirective_e od, lz4b_tabletype tt, dictDirective_e dd, dictIssue_e di, int acceleration)
{
    const uint8_t* ip = source;
    const uint32_t startIndex = cctx->currentOffset;
    const uint8_t* base = source - startIndex;
    const uint8_t* lowLimit;
    const lz4b_stream* dictCtx = cctx->dictCtx;
    const uint8_t* const dictionary = (dd == DD_DICTCTX) ? dictCtx->dictionary : cctx->dictionary;
    const uint32_t dictSize = (dd == DD_DICTCTX) ? dictCtx->dictSize : cctx->dictSize;
    const uint32_t dictDelta = (dd == DD_DICTCTX) ? startIndex - dictCtx->currentOffset : 0;
    const int maybe_extMem = (dd == DD_EXTDICT) || (dd == DD_DICTCTX);
    const uint32_t prefixIdxLimit = startIndex - dictSize;
    const uint8_t* const dictEnd = dictionary ? dictionary + dictSize : dictionary;
    const uint8_t* anchor = source;
    const uint8_t* const iend = ip + inputSize;
    const uint8_t* const mflimitPlusOne = iend - MFLIMIT + 1;
    const uint8_t* const matchlimit = iend - LASTLITERALS;
    const uint8_t* dictBase = (dictionary == NULL) ? NULL :
        (dd == DD_DICTCTX) ? dictionary + dictSize - dictCtx->currentOffset : dictionary + dictSize - startIndex;
    uint8_t* op = dest;
    uint8_t* const olimit = op + maxOutputSize;
    uint32_t offset = 0;
    uint32_t forwardH;

    if (inputSize == 0) {
        /* handled by caller semantics: just emit an empty literal token */
    }
    if ((tt == TT_BYU16) && (inputSize >= LIMIT_64K)) return 0;
    if (acceleration < 1) acceleration = 1;

    lowLimit = source - (dd == DD_PREFIX64K ? dictSize : 0);

    if (dd == DD_DICTCTX) {
        cctx->dictCtx = NULL;
        cctx->dictSize = (uint32_t)inputSize;
    } else {
        cctx->dictSize += (uint32_t)inputSize;
    }
    cctx->currentOffset += (uint32_t)inputSize;
    cctx->tableType = (uint32_t)tt;

    if (inputSize < MINLENGTH) goto _last_literals;

    /* first byte */
    { uint32_t h = hashPos(ip, tt); putIndex(startIndex, h, cctx->hashTable, tt); }
    ip++; forwardH = hashPos(ip, tt);

    for (;;) {
        const uint8_t* match;
        uint8_t* token;

        {
            const uint8_t* forwardIp = ip;
            int step = 1;
            int searchMatchNb = acceleration << SKIPTRIGGER;
            do {
                uint32_t const h = forwardH;
                uint32_t const current = (uint32_t)(forwardIp - base);
                uint32_t matchIndex = getIndex(h, cctx->hashTable, tt);
                ip = forwardIp;
                forwardIp += step;
                step = (searchMatchNb++ >> SKIPTRIGGER);
                if (forwardIp > mflimitPlusOne) goto _last_literals;

                if (dd == DD_DICTCTX) {
                    if (matchIndex < startIndex) {
                        matchIndex = getIndex(h, dictCtx->hashTable, TT_BYU32);
                        match = dictBase + matchIndex;
                        matchIndex += dictDelta;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = source;
                    }
                } else if (dd == DD_EXTDICT) {
                    if (matchIndex < startIndex) {
                        match = dictBase + matchIndex;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = source;
                    }
                } else {
                    match = base + matchIndex;
                }
                forwardH = hashPos(forwardIp, tt);
                putIndex(current, h, cctx->hashTable, tt);

                if ((di == DI_SMALL) && (matchIndex < prefixIdxLimit)) continue;
                if ((tt != TT_BYU16) && (matchIndex + LZ4B_DISTANCE_MAX < current)) continue;
                if (rd32(match) == rd32(ip)) {
                    if (maybe_extMem) offset = current - matchIndex;
                    break;
                }
            } while (1);
        }

        /* catch up */
        if ((match > lowLimit) && (ip[-1] == match[-1])) {
            do { ip--; match--; } while (((ip > anchor) & (match > lowLimit)) && (ip[-1] == match[-1]));
        }

        /* encode literals */
        {
            unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if ((od == OD_LIMITED) && (op + litLength + (2 + 1 + LASTLITERALS) + (litLength / 255) > olimit)) return 0;
            if (litLength >= RUN_MASK) {
                unsigned len = litLength - RUN_MASK;
                *token = (uint8_t)(RUN_MASK << ML_BITS);
                for (; len >= 255; len -= 255) *op++ = 255;
                *op++ = (uint8_t)len;
            } else *token = (uint8_t)(litLength << ML_BITS);
            memcpy(op, anchor, litLength);
            op += litLength;
        }

_next_match:
        /* encode offset */
        if (maybe_extMem) { wr16(op, (uint16_t)offset); op += 2; }
        else { wr16(op, (uint16_t)(ip - match)); op += 2; }

        /* encode match length */
        {
            unsigned matchCode;
            if ((dd == DD_EXTDICT || dd == DD_DICTCTX) && (lowLimit == dictionary)) {
                const uint8_t* limit = ip + (dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = countMatch(ip + LZ4B_MINMATCH, match + LZ4B_MINMATCH, limit);
                ip += (size_t)matchCode + LZ4B_MINMATCH;
                if (ip == limit) {
                    unsigned const more = countMatch(limit, source, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = countMatch(ip + LZ4B_MINMATCH, match + LZ4B_MINMATCH, matchlimit);
                ip += (size_t)matchCode + LZ4B_MINMATCH;
            }
            if ((od == OD_LIMITED) && (op + (1 + LASTLITERALS) + (matchCode + 240) / 255 > olimit)) return 0;
            if (matchCode >= ML_MASK) {
                *token += ML_MASK;
                matchCode -= ML_MASK;
                wr32(op, 0xFFFFFFFF);
                while (matchCode >= 4 * 255) { op += 4; wr32(op, 0xFFFFFFFF); matchCode -= 4 * 255; }
                op += matchCode / 255;
                *op++ = (uint8_t)(matchCode % 255);
            } else *token += (uint8_t)matchCode;
        }

        anchor = ip;
        if (ip >= mflimitPlusOne) break;

        /* fill table */
        { uint32_t h = hashPos(ip - 2, tt); uint32_t idx = (uint32_t)((ip - 2) - base); putIndex(idx, h, cctx->hashTable, tt); }

        /* test next position */
        {
            uint32_t const h = hashPos(ip, tt);
            uint32_t const current = (uint32_t)(ip - base);
            uint32_t matchIndex = getIndex(h, cctx->hashTable, tt);
            if (dd == DD_DICTCTX) {
                if (matchIndex < startIndex) {
                    matchIndex = getIndex(h, dictCtx->hashTable, TT_BYU32);
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                    matchIndex += dictDelta;
                } else {
                    match = base + matchIndex;
                    lowLimit = source;
                }
            } else if (dd == DD_EXTDICT) {
                if (matchIndex < startIndex) {
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                } else {
                    match = base + matchIndex;
                    lowLimit = source;
                }
            } else {
                match = base + matchIndex;
            }
            putIndex(current, h, cctx->hashTable, tt);
            if (((di == DI_SMALL) ? (matchIndex >= prefixIdxLimit) : 1)
                && ((tt == TT_BYU16) ? 1 : (matchIndex + LZ4B_DISTANCE_MAX >= current))
                && (rd32(match) == rd32(ip))) {
                token = op++;
                *token = 0;
                if (maybe_extMem) offset = current - matchIndex;
                goto _next_match;
            }
        }

        forwardH = hashPos(++ip, tt);
    }

_last_literals:
    {
        size_t lastRun = (size_t)(iend - anchor);
        if ((od == OD_LIMITED) && (op + lastRun + 1 + ((lastRun + 255 - RUN_MASK) / 255) > olimit)) return 0;
        if (lastRun >= RUN_MASK) {
            size_t accumulator = lastRun - RUN_MASK;
            *op++ = (uint8_t)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (uint8_t)accumulator;
        } else {
            *op++ = (uint8_t)(lastRun << ML_BITS);
        }
        memcpy(op, anchor, lastRun);
        op += lastRun;
    }
    return (int)(op - dest);
}

int lz4b_compress_fast_extState_fastReset(lz4b_stream* ctx, const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity, int acceleration)
{
    if (acceleration < 1) acceleration = 1;
    if (acceleration > 65537) acceleration = 65537;
    if (dstCapacity >= lz4b_compressBound(srcSize)) {
        if (srcSize < LIMIT_64K) {
            prepareTable(ctx, srcSize, TT_BYU16);
            if (ctx->currentOffset)
                return compress_generic(ctx, src, dst, srcSize, 0, OD_NOTLIMITED, TT_BYU16, DD_NODICT, DI_SMALL, acceleration);
            return compress_generic(ctx, src, dst, srcSize, 0, OD_NOTLIMITED, TT_BYU16, DD_NODICT, DI_NONE, acceleration);
        } else {
            prepareTable(ctx, srcSize, TT_BYU32);
            return compress_generic(ctx, src, dst, srcSize, 0, OD_NOTLIMITED, TT_BYU32, DD_NODICT, DI_NONE, acceleration);
        }
    } else {
        if (srcSize < LIMIT_64K) {
            prepareTable(ctx, srcSize, TT_BYU16);
            if (ctx->currentOffset)
                return compress_generic(ctx, src, dst, srcSize, dstCapacity, OD_LIMITED, TT_BYU16, DD_NODICT, DI_SMALL, acceleration);
            return compress_generic(ctx, src, dst, srcSize, dstCapacity, OD_LIMITED, TT_BYU16, DD_NODICT, DI_NONE, acceleration);
        } else {
            prepareTable(ctx, srcSize, TT_BYU32);
            return compress_generic(ctx, src, dst, srcSize, dstCapacity, OD_LIMITED, TT_BYU32, DD_NODICT, DI_NONE, acceleration);
        }
    }
}

int lz4b_compress_fast(const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity, int acceleration)
{
    lz4b_stream* ctx = (lz4b_stream*)calloc(1, sizeof(lz4b_stream));
    int r;
    if (!ctx) return 0;
    r = lz4b_compress_fast_extState_fastReset(ctx, src, dst, srcSize, dstCapacity, acceleration);
    free(ctx);
    return r;
}

static int loadDict_internal(lz4b_stream* dict, const uint8_t* dictionary, int dictSize, int slow)
{
    const uint8_t* p = dictionary;
    const uint8_t* const dictEnd = p + dictSize;
    uint32_t idx32;
    lz4b_resetStream(dict);
    dict->currentOffset += 64 KB;
    if (dictSize < 4) return 0;
    if ((dictEnd - p) > 64 KB) p = dictEnd - 64 KB;
    dict->dictionary = p;
    dict->dictSize = (uint32_t)(dictEnd - p);
    dict->tableType = TT_BYU32;
    idx32 = dict->currentOffset - dict->dictSize;
    if (slow) {
        while (p <= dictEnd - 4) {
            uint32_t h = hashPos(p, TT_BYU32);
            putIndex(idx32, h, dict->hashTable, TT_BYU32);
            p += 1; idx32 += 1;
        }
    } else {
        while (p <= dictEnd - 4) {
            uint32_t h = hashPos(p, TT_BYU32);
            putIndex(idx32, h, dict->hashTable, TT_BYU32);
            p += 3; idx32 += 3;
        }
    }
    return (int)dict->dictSize;
}
int lz4b_loadDict(lz4b_stream* s, const uint8_t* dict, int dictSize) { return loadDict_internal(s, dict, dictSize, 0); }
int lz4b_loadDictSlow(lz4b_stream* s, const uint8_t* dict, int dictSize) { return loadDict_internal(s, dict, dictSize, 1); }

void lz4b_attach_dictionary(lz4b_stream* working, const lz4b_stream* dict)
{
    if (dict == NULL || dict->dictSize == 0) {
        prepareTable(working, 0, TT_BYU32);  /* ensure clean state */
        working->dictCtx = NULL;
        return;
    }
    prepareTable(working, 0, TT_BYU32);
    working->dictCtx = dict;
    working->dictionary = NULL;
    working->dictSize = 0;
    if (working->currentOffset != 0) working->currentOffset += 64 KB;
}

static void renormDict(lz4b_stream* d, int nextSize)
{
    if (d->currentOffset + (unsigned)nextSize > 0x80000000) {
        uint32_t const delta = d->currentOffset - 64 KB;
        const uint8_t* dictEnd = d->dictionary + d->dictSize;
        unsigned i;
        for (i = 0; i < LZ4B_HASH_SIZE_U32; i++) {
            if (d->hashTable[i] < delta) d->hashTable[i] = 0;
            else d->hashTable[i] -= delta;
        }
        d->currentOffset = 64 KB;
        if (d->dictSize > 64 KB) d->dictSize = 64 KB;
        d->dictionary = dictEnd - d->dictSize;
    }
}

int lz4b_compress_fast_continue(lz4b_stream* s, const uint8_t* source, uint8_t* dest, int inputSize, int maxOutputSize, int acceleration)
{
    const uint8_t* dictEnd = s->dictSize ? s->dictionary + s->dictSize : NULL;
    renormDict(s, inputSize);
    if (acceleration < 1) acceleration = 1;
    if (acceleration > 65537) acceleration = 65537;

    if ((s->dictSize < 4) && (dictEnd != source) && (inputSize > 0) && (s->dictCtx == NULL)) {
        s->dictSize = 0;
        s->dictionary = source;
        dictEnd = source;
    }
    {
        const uint8_t* const sourceEnd = source + inputSize;
        if ((sourceEnd > s->dictionary) && (sourceEnd < dictEnd)) {
            s->dictSize = (uint32_t)(dictEnd - sourceEnd);
            if (s->dictSize > 64 KB) s->dictSize = 64 KB;
            if (s->dictSize < 4) s->dictSize = 0;
            s->dictionary = dictEnd - s->dictSize;
        }
    }
    if (dictEnd == source) {
        if ((s->dictSize < 64 KB) && (s->dictSize < s->currentOffset))
            return compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_PREFIX64K, DI_SMALL, acceleration);
        return compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_PREFIX64K, DI_NONE, acceleration);
    }
    {
        int result;
        if (s->dictCtx) {
            if (inputSize > 4 KB) {
                memcpy(s, s->dictCtx, sizeof(*s));
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_EXTDICT, DI_NONE, acceleration);
            } else {
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_DICTCTX, DI_NONE, acceleration);
            }
        } else {
            if ((s->dictSize < 64 KB) && (s->dictSize < s->currentOffset))
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_EXTDICT, DI_SMALL, acceleration);
            else
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, OD_LIMITED, TT_BYU32, DD_EXTDICT, DI_NONE, acceleration);
        }
        s->dictionary = source;
        s->dictSize = (uint32_t)inputSize;
        return result;
    }
}

int lz4b_saveDict(lz4b_stream* d, uint8_t* safeBuffer, int dictSize)
{
    if ((uint32_t)dictSize > 64 KB) dictSize = 64 KB;
    if ((uint32_t)dictSize > d->dictSize) dictSize = (int)d->dictSize;
    if (dictSize > 0) {
        const uint8_t* const previousDictEnd = d->dictionary + d->dictSize;
        memmove(safeBuffer, previousDictEnd - dictSize, (size_t)dictSize);
    }
    d->dictionary = safeBuffer;
    d->dictSize = (uint32_t)dictSize;
    return dictSize;
}

/* ---------------- decompression ---------------- */
/* Safe decoder: returns number of bytes decoded, or negative on error.
 * dict: external dictionary (may be NULL). If dict + dictSize == dst, it acts as prefix. */
static int decompress_generic(const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity,
                              const uint8_t* dictStart, size_t dictSize)
{
    const uint8_t* ip = src;
    const uint8_t* const iend = ip + srcSize;
    uint8_t* op = dst;
    uint8_t* const oend = op + dstCapacity;
    const uint8_t* const dictEnd = (dictStart == NULL) ? NULL : dictStart + dictSize;
    const uint8_t* lowPrefix = dst;  /* start of current prefix */
    int const prefixMode = (dictStart != NULL && dictEnd == dst);

    if (srcSize == 0) return -1;
    if (dstCapacity == 0) {
        /* only an empty block (single zero token) is acceptable */
        return (srcSize == 1 && *ip == 0) ? 0 : -1;
    }
    if (prefixMode) lowPrefix = dst - dictSize;

    for (;;) {
        unsigned token;
        size_t length;
        const uint8_t* match;
        size_t offset;
        if (ip >= iend) return -1;
        token = *ip++;
        length = token >> ML_BITS;
        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
            if (length > (size_t)(oend - op) || length > (size_t)(iend - ip)) return -1;
        }
        /* literals */
        if ((size_t)(oend - op) < length || (size_t)(iend - ip) < length) return -1;
        memcpy(op, ip, length);
        ip += length; op += length;
        if (ip == iend) {
            /* end of block: last sequence is literals only */
            break;
        }
        if (ip + 2 > iend) return -1;
        offset = rd16(ip); ip += 2;
        if (offset == 0) return -1;
        match = op - offset;
        length = token & ML_MASK;
        if (length == ML_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
        }
        length += LZ4B_MINMATCH;
        if ((size_t)(oend - op) < length) return -1;
        /* match validity */
        if (match < lowPrefix) {
            /* must be within external dictionary (non-prefix) */
            size_t extLen;
            if (prefixMode || dictStart == NULL) return -1;
            if ((size_t)(lowPrefix - match) > dictSize) return -1;
            {
                const uint8_t* dmatch = dictEnd - (lowPrefix - match);
                extLen = (size_t)(dictEnd - dmatch);
                if (extLen >= length) {
                    memmove(op, dmatch, length);
                    op += length;
                    continue;
                }
                memcpy(op, dmatch, extLen);
                op += extLen;
                length -= extLen;
                match = lowPrefix;
            }
        }
        /* overlapping copy */
        {
            size_t i;
            if (offset >= 8 && (size_t)(match + length) <= (size_t)op) {
                memcpy(op, match, length);
            } else {
                for (i = 0; i < length; i++) op[i] = match[i];
            }
            op += length;
        }
    }
    return (int)(op - dst);
}

int lz4b_decompress_safe(const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity)
{
    return decompress_generic(src, dst, srcSize, dstCapacity, NULL, 0);
}

int lz4b_decompress_safe_usingDict(const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity, const uint8_t* dict, int dictSize)
{
    if (dictSize == 0) return decompress_generic(src, dst, srcSize, dstCapacity, NULL, 0);
    return decompress_generic(src, dst, srcSize, dstCapacity, dict, (size_t)dictSize);
}
