#include <string.h>
/* chunked model: chunk of chunkSize, blocks of blockSize inside; new ctx per chunk with dict loaded by method */
int main(int argc, char** argv) {
    FILE* f = fopen(argv[1], "rb"); fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(sz + 1); if (fread(buf, 1, sz, f) != (size_t)sz) return 1; fclose(f);
    int acc = atoi(argv[2]);
    long blockSize = atol(argv[3]);
    long chunkSize = atol(argv[4]);
    int method = atoi(argv[5]); /* 0 loadDict prefix, 1 loadDict ext, 2 loadDictSlow prefix, 3 loadDictSlow ext */
    const char* outName = argv[6];
    FILE* fo = fopen(outName, "wb");
    uint8_t* out = malloc(lz4b_compressBound(blockSize));
    uint8_t* work = malloc(65536 + chunkSize);
    lz4b_stream* s = calloc(1, sizeof(lz4b_stream));
    for (long cp = 0; cp < sz; cp += chunkSize) {
        long cn = (sz - cp) < chunkSize ? (sz - cp) : chunkSize;
        long dstart = cp - 65536; if (dstart < 0) dstart = 0;
        int dsize = (int)(cp - dstart);
        const uint8_t* src;
        memcpy(work, buf + dstart, dsize);
        lz4b_resetStream(s);
        if (method == 0 || method == 1) { if (dsize) lz4b_loadDict(s, work, dsize); }
        else { if (dsize) lz4b_loadDictSlow(s, work, dsize); }
        if (method == 0 || method == 2) { memcpy(work + dsize, buf + cp, cn); src = work + dsize; }
        else src = buf + cp;
        for (long p = 0; p < cn; p += blockSize) {
            int n = (cn - p) < blockSize ? (int)(cn - p) : (int)blockSize;
            int c = lz4b_compress_fast_continue(s, src + p, out, n, lz4b_compressBound(blockSize), acc);
            printf("%d ", c);
            fwrite(out, 1, c, fo);
        }
    }
    printf("\n");
    fclose(fo);
    return 0;
}
