cat > /workspace/src/lz4hc.c <<'EOF'
/* LZ4 HC compressor - original reimplementation of the hash-chain and
 * optimal-parsing strategies used by the LZ4 high compression mode. */
#include "lz4hc.h"
#include <string.h>
#include <stdlib.h>

#define MINMATCH 4
#define ML_BITS 4
#define ML_MASK ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define MFLIMIT 12
#define LASTLITERALS 5
#define MINLENGTH (MFLIMIT + 1)
#define DISTANCE_MAX 65535
#define OPTIMAL_ML (int)((ML_MASK - 1) + MINMATCH)
#define LZ4_OPT_NUM (1 << 12)
#define KB *(1 << 10)
#define GB *(1U << 30)

typedef enum { noDictCtx, usingDictCtxHc } dictCtx_directive;
typedef enum { favorCompressionRatio = 0, favorDecompressionSpeed } HCfavor_e;
typedef enum { notLimited = 0, limitedOutput = 1 } limitedOutput_directive;

static inline uint16_t rd16(const void* p) { uint16_t v; memcpy(&v, p, 2); return v; }
static inline uint32_t rd32(const void* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline uint64_t rd64(const void* p) { uint64_t v; memcpy(&v, p, 8); return v; }
static inline void wr16(void* p, uint16_t v) { memcpy(p, &v, 2); }

static inline uint32_t hcHash(const uint8_t* p) { return (rd32(p) * 2654435761U) >> ((MINMATCH * 8) - LZ4HC_HASH_LOG); }
#define DELTANEXTU16(table, pos) ((table)[(uint16_t)(pos)])
#define MAX(a,b) ((a) > (b) ? (a) : (b))
#define MIN(a,b) ((a) < (b) ? (a) : (b))

static inline unsigned countMatch(const uint8_t* pIn, const uint8_t* pMatch, const uint8_t* pInLimit) {
    const uint8_t* const pStart = pIn;
    if (pIn < pInLimit - 7) {
        uint64_t d = rd64(pMatch) ^ rd64(pIn);
        if (d) return (unsigned)__builtin_ctzll(d) >> 3;
        pIn += 8; pMatch += 8;
    }
    while (pIn < pInLimit - 7) {
        uint64_t d = rd64(pMatch) ^ rd64(pIn);
        if (!d) { pIn += 8; pMatch += 8; continue; }
        pIn += (unsigned)__builtin_ctzll(d) >> 3;
        return (unsigned)(pIn - pStart);
    }
    if ((pIn < pInLimit - 3) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

static void clearTables(lz4hc_ctx* hc4) {
    memset(hc4->hashTable, 0, sizeof(hc4->hashTable));
    memset(hc4->chainTable, 0xFF, sizeof(hc4->chainTable));
}

static void init_internal(lz4hc_ctx* hc4, const uint8_t* start) {
    size_t const bufferSize = (size_t)(hc4->end - hc4->prefixStart);
    size_t newStartingOffset = bufferSize + hc4->dictLimit;
    if (newStartingOffset > 1 GB) { clearTables(hc4); newStartingOffset = 0; }
    newStartingOffset += 64 KB;
    hc4->nextToUpdate = (uint32_t)newStartingOffset;
    hc4->prefixStart = start;
    hc4->end = start;
    hc4->dictStart = start;
    hc4->dictLimit = (uint32_t)newStartingOffset;
    hc4->lowLimit = (uint32_t)newStartingOffset;
}

void lz4hc_setCompressionLevel(lz4hc_ctx* ctx, int compressionLevel) {
    if (compressionLevel < 1) compressionLevel = LZ4HC_CLEVEL_DEFAULT;
    if (compressionLevel > LZ4HC_CLEVEL_MAX) compressionLevel = LZ4HC_CLEVEL_MAX;
    ctx->compressionLevel = (short)compressionLevel;
}
void lz4hc_favorDecompressionSpeed(lz4hc_ctx* ctx, int favor) { ctx->favorDecSpeed = (favor != 0); }

void lz4hc_initStream(lz4hc_ctx* ctx) {
    memset(ctx, 0, sizeof(*ctx));  /* hash table zero; chain table set at init */
    clearTables(ctx);
    ctx->end = NULL; ctx->prefixStart = NULL; ctx->dictStart = NULL;
    ctx->dictLimit = 0; ctx->lowLimit = 0; ctx->nextToUpdate = 0;
    ctx->dirty = 0;
    lz4hc_setCompressionLevel(ctx, LZ4HC_CLEVEL_DEFAULT);
}

void lz4hc_resetStream_fast(lz4hc_ctx* s, int compressionLevel) {
    if (s->dirty) {
        lz4hc_initStream(s);
    } else {
        s->end -= (uintptr_t)s->prefixStart;
        s->prefixStart = NULL;
        s->dictStart = NULL;
        s->dictCtx = NULL;
    }
    lz4hc_setCompressionLevel(s, compressionLevel);
}

/* insert all positions from nextToUpdate up to (excluding) ip */
static void hcInsert(lz4hc_ctx* hc4, const uint8_t* ip) {
    uint16_t* const chainTable = hc4->chainTable;
    uint32_t* const hashTable = hc4->hashTable;
    const uint8_t* const prefixPtr = hc4->prefixStart;
    uint32_t const prefixIdx = hc4->dictLimit;
    uint32_t const target = (uint32_t)(ip - prefixPtr) + prefixIdx;
    uint32_t idx = hc4->nextToUpdate;
    while (idx < target) {
        uint32_t const h = hcHash(prefixPtr + idx - prefixIdx);
        size_t delta = idx - hashTable[h];
        if (delta > DISTANCE_MAX) delta = DISTANCE_MAX;
        DELTANEXTU16(chainTable, idx) = (uint16_t)delta;
        hashTable[h] = idx;
        idx++;
    }
    hc4->nextToUpdate = target;
}

static int countBack(const uint8_t* const ip, const uint8_t* const match, const uint8_t* const iMin, const uint8_t* const mMin) {
    int back = 0;
    int const min = (int)MAX(iMin - ip, mMin - match);
    while ((back > min) && (ip[back - 1] == match[back - 1])) back--;
    return back;
}

static unsigned countPattern(const uint8_t* ip, const uint8_t* const iEnd, uint32_t const pattern32) {
    const uint8_t* const iStart = ip;
    uint64_t const pattern = (uint64_t)pattern32 + (((uint64_t)pattern32) << 32);
    while (ip < iEnd - 7) {
        uint64_t const diff = rd64(ip) ^ pattern;
        if (!diff) { ip += 8; continue; }
        ip += (unsigned)__builtin_ctzll(diff) >> 3;
        return (unsigned)(ip - iStart);
    }
    {
        uint64_t patternByte = pattern;
        while ((ip < iEnd) && (*ip == (uint8_t)patternByte)) { ip++; patternByte >>= 8; }
    }
    return (unsigned)(ip - iStart);
}

static unsigned reverseCountPattern(const uint8_t* ip, const uint8_t* const iLow, uint32_t pattern) {
    const uint8_t* const iStart = ip;
    while (ip >= iLow + 4) {
        if (rd32(ip - 4) != pattern) break;
        ip -= 4;
    }
    {
        const uint8_t* bytePtr = (const uint8_t*)(&pattern) + 3;
        while (ip > iLow) {
            if (ip[-1] != *bytePtr) break;
            ip--; bytePtr--;
        }
    }
    return (unsigned)(iStart - ip);
}

static int protectDictEnd(uint32_t const dictLimit, uint32_t const matchIndex) {
    return ((uint32_t)((dictLimit - 1) - matchIndex) >= 3);
}

static uint32_t rotl32(uint32_t x, int r) { return (x << r) | (x >> (32 - r)); }
static uint32_t rotatePattern(size_t const rotate, uint32_t const pattern) {
    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
    if (bitsToRotate == 0) return pattern;
    return rotl32(pattern, (int)bitsToRotate);
}

typedef enum { rep_untested, rep_not, rep_confirmed } repeat_state_e;

static int insertAndGetWiderMatch(lz4hc_ctx* const hc4, const uint8_t* const ip,
                                  const uint8_t* const iLowLimit, const uint8_t* const iHighLimit,
                                  int longest, const uint8_t** matchpos, const uint8_t** startpos,
                                  const int maxNbAttempts, const int patternAnalysis, const int chainSwap,
                                  const dictCtx_directive dict, const HCfavor_e favorDecSpeed)
{
    uint16_t* const chainTable = hc4->chainTable;
    uint32_t* const HashTable = hc4->hashTable;
    const lz4hc_ctx* const dictCtx = hc4->dictCtx;
    const uint8_t* const prefixPtr = hc4->prefixStart;
    const uint32_t prefixIdx = hc4->dictLimit;
    const uint32_t ipIndex = (uint32_t)(ip - prefixPtr) + prefixIdx;
    const int withinStartDistance = (hc4->lowLimit + (DISTANCE_MAX + 1) > ipIndex);
    const uint32_t lowestMatchIndex = (withinStartDistance) ? hc4->lowLimit : ipIndex - DISTANCE_MAX;
    const uint8_t* const dictStart = hc4->dictStart;
    const uint32_t dictIdx = hc4->lowLimit;
    const uint8_t* const dictEnd = dictStart + prefixIdx - dictIdx;
    int const lookBackLength = (int)(ip - iLowLimit);
    int nbAttempts = maxNbAttempts;
    uint32_t matchChainPos = 0;
    uint32_t const pattern = rd32(ip);
    uint32_t matchIndex;
    repeat_state_e repeat = rep_untested;
    size_t srcPatternLength = 0;

