                    const uint8_t* const matchPtr = extDict ? dictStart + (matchCandidateIdx - dictIdx) : prefixPtr + (matchCandidateIdx - prefixIdx);
                    if (rd32(matchPtr) == pattern) {
                        const uint8_t* const iLimit = extDict ? dictEnd : iHighLimit;
                        size_t forwardPatternLength = countPattern(matchPtr + sizeof(pattern), iLimit, pattern) + sizeof(pattern);
                        if (extDict && matchPtr + forwardPatternLength == iLimit) {
                            uint32_t const rotatedPattern = rotatePattern(forwardPatternLength, pattern);
                            forwardPatternLength += countPattern(prefixPtr, iHighLimit, rotatedPattern);
                        }
                        {
                            const uint8_t* const lowestMatchPtr = extDict ? dictStart : prefixPtr;
                            size_t backLength = reverseCountPattern(matchPtr, lowestMatchPtr, pattern);
                            size_t currentSegmentLength;
                            if (!extDict && matchPtr - backLength == prefixPtr && dictIdx < prefixIdx) {
                                uint32_t const rotatedPattern = rotatePattern((uint32_t)(-(int)backLength), pattern);
                                backLength += reverseCountPattern(dictEnd, dictStart, rotatedPattern);
                            }
                            backLength = matchCandidateIdx - MAX(matchCandidateIdx - (uint32_t)backLength, lowestMatchIndex);
                            currentSegmentLength = backLength + forwardPatternLength;
                            if ((currentSegmentLength >= srcPatternLength) && (forwardPatternLength <= srcPatternLength)) {
                                uint32_t const newMatchIndex = matchCandidateIdx + (uint32_t)forwardPatternLength - (uint32_t)srcPatternLength;
                                if (protectDictEnd(prefixIdx, newMatchIndex))
                                    matchIndex = newMatchIndex;
                                else
                                    matchIndex = prefixIdx;
                            } else {
                                uint32_t const newMatchIndex = matchCandidateIdx - (uint32_t)backLength;
                                if (!protectDictEnd(prefixIdx, newMatchIndex)) {
                                    matchIndex = prefixIdx;
                                } else {
                                    matchIndex = newMatchIndex;
                                    if (lookBackLength == 0) {
                                        size_t const maxML = MIN(currentSegmentLength, srcPatternLength);
                                        if ((size_t)longest < maxML) {
                                            if ((size_t)(ip - prefixPtr) + prefixIdx - matchIndex > DISTANCE_MAX) break;
                                            longest = (int)maxML;
                                            *matchpos = prefixPtr - prefixIdx + matchIndex;
                                            *startpos = ip;
                                        }
                                        {
                                            uint32_t const distToNextPattern = DELTANEXTU16(chainTable, matchIndex);
                                            if (distToNextPattern > matchIndex) break;
                                            matchIndex -= distToNextPattern;
                                        }
                                    }
                                }
                            }
                        }
                        continue;
                    }
                }
            }
        }

        matchIndex -= DELTANEXTU16(chainTable, matchIndex + matchChainPos);
    }

    if (dict == usingDictCtxHc && nbAttempts > 0 && withinStartDistance) {
        size_t const dictEndOffset = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
        uint32_t dictMatchIndex = dictCtx->hashTable[hcHash(ip)];
        matchIndex = dictMatchIndex + lowestMatchIndex - (uint32_t)dictEndOffset;
        while (ipIndex - matchIndex <= DISTANCE_MAX && nbAttempts--) {
            const uint8_t* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + dictMatchIndex;
            if (rd32(matchPtr) == pattern) {
                int mlt;
                int back = 0;
                const uint8_t* vLimit = ip + (dictEndOffset - dictMatchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                mlt = (int)countMatch(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                back = lookBackLength ? countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
                mlt -= back;
                if (mlt > longest) {
                    longest = mlt;
                    *matchpos = prefixPtr - prefixIdx + matchIndex + back;
                    *startpos = ip + back;
                }
            }
            {
                uint32_t const nextOffset = DELTANEXTU16(dictCtx->chainTable, dictMatchIndex);
                dictMatchIndex -= nextOffset;
                matchIndex -= nextOffset;
            }
        }
    }
    return longest;
}

static int insertAndFindBestMatch(lz4hc_ctx* const hc4, const uint8_t* const ip, const uint8_t* const iLimit,
                                  const uint8_t** matchpos, const int maxNbAttempts, const int patternAnalysis, const dictCtx_directive dict)
{
    const uint8_t* uselessPtr = ip;
    return insertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH - 1, matchpos, &uselessPtr, maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
}

/* returns 1 on output overflow */
static int encodeSequence(const uint8_t** _ip, uint8_t** _op, const uint8_t** _anchor, int matchLength, const uint8_t* const match,
                          limitedOutput_directive limit, uint8_t* oend)
{
#define ip (*_ip)
#define op (*_op)
#define anchor (*_anchor)
    size_t length;
    uint8_t* const token = op++;
    length = (size_t)(ip - anchor);
    if (limit && ((op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend)) return 1;
    if (length >= RUN_MASK) {
        size_t len = length - RUN_MASK;
        *token = (uint8_t)(RUN_MASK << ML_BITS);
        for (; len >= 255; len -= 255) *op++ = 255;
        *op++ = (uint8_t)len;
    } else {
        *token = (uint8_t)(length << ML_BITS);
    }
    memcpy(op, anchor, length);
    op += length;
    wr16(op, (uint16_t)(ip - match)); op += 2;
    length = (size_t)matchLength - MINMATCH;
    if (limit && (op + (length / 255) + (1 + LASTLITERALS) > oend)) return 1;
    if (length >= ML_MASK) {
        *token += ML_MASK;
        length -= ML_MASK;
        for (; length >= 510; length -= 510) { *op++ = 255; *op++ = 255; }
        if (length >= 255) { length -= 255; *op++ = 255; }
        *op++ = (uint8_t)length;
    } else {
        *token += (uint8_t)length;
    }
    ip += matchLength;
    anchor = ip;
    return 0;
#undef ip
#undef op
#undef anchor
}

static int compress_hashChain(lz4hc_ctx* const ctx, const uint8_t* const source, uint8_t* const dest, int* srcSizePtr,
                              int const maxOutputSize, int maxNbAttempts, const limitedOutput_directive limit, const dictCtx_directive dict)
{
    const int inputSize = *srcSizePtr;
    const int patternAnalysis = (maxNbAttempts > 128);

    const uint8_t* ip = source;
    const uint8_t* anchor = ip;
    const uint8_t* const iend = ip + inputSize;
    const uint8_t* const mflimit = iend - MFLIMIT;
    const uint8_t* const matchlimit = (iend - LASTLITERALS);

    uint8_t* op = dest;
    uint8_t* oend = op + maxOutputSize;

    int ml0, ml, ml2, ml3;
    const uint8_t* start0;
    const uint8_t* ref0;
    const uint8_t* ref = NULL;
    const uint8_t* start2 = NULL;
    const uint8_t* ref2 = NULL;
    const uint8_t* start3 = NULL;
    const uint8_t* ref3 = NULL;

    *srcSizePtr = 0;
    if (inputSize < MINLENGTH) goto _last_literals;

    while (ip <= mflimit) {
        ml = insertAndFindBestMatch(ctx, ip, matchlimit, &ref, maxNbAttempts, patternAnalysis, dict);
        if (ml < MINMATCH) { ip++; continue; }

        start0 = ip; ref0 = ref; ml0 = ml;

_Search2:
        if (ip + ml <= mflimit) {
            ml2 = insertAndGetWiderMatch(ctx, ip + ml - 2, ip + 0, matchlimit, ml, &ref2, &start2,
                                         maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml2 = ml;
        }

        if (ml2 == ml) {
            if (encodeSequence(&ip, &op, &anchor, ml, ref, limit, oend)) goto _dest_overflow;
            continue;
        }

        if (start0 < ip) {
            if (start2 < ip + ml0) {
                ip = start0; ref = ref0; ml = ml0;
            }
        }

        if ((start2 - ip) < 3) {
            ml = ml2;
            ip = start2;
            ref = ref2;
            goto _Search2;
        }

_Search3:
        if ((start2 - ip) < OPTIMAL_ML) {
            int correction;
            int new_ml = ml;
            if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
            if (ip + new_ml > start2 + ml2 - MINMATCH) new_ml = (int)(start2 - ip) + ml2 - MINMATCH;
            correction = new_ml - (int)(start2 - ip);
            if (correction > 0) {
                start2 += correction;
                ref2 += correction;
                ml2 -= correction;
            }
        }

        if (start2 + ml2 <= mflimit) {
            ml3 = insertAndGetWiderMatch(ctx, start2 + ml2 - 3, start2, matchlimit, ml2, &ref3, &start3,
                                         maxNbAttempts, patternAnalysis, 0, dict, favorCompressionRatio);
        } else {
            ml3 = ml2;
        }

        if (ml3 == ml2) {
            if (start2 < ip + ml) ml = (int)(start2 - ip);
            if (encodeSequence(&ip, &op, &anchor, ml, ref, limit, oend)) goto _dest_overflow;
            ip = start2;
            if (encodeSequence(&ip, &op, &anchor, ml2, ref2, limit, oend)) goto _dest_overflow;
            continue;
        }

        if (start3 < ip + ml + 3) {
            if (start3 >= (ip + ml)) {
                if (start2 < ip + ml) {
                    int correction = (int)(ip + ml - start2);
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                    if (ml2 < MINMATCH) {
                        start2 = start3;
                        ref2 = ref3;
                        ml2 = ml3;
                    }
                }
                if (encodeSequence(&ip, &op, &anchor, ml, ref, limit, oend)) goto _dest_overflow;
                ip = start3;
                ref = ref3;
                ml = ml3;

                start0 = start2;
                ref0 = ref2;
                ml0 = ml2;
                goto _Search2;
            }
            start2 = start3;
            ref2 = ref3;
            ml2 = ml3;
            goto _Search3;
        }

        if (start2 < ip + ml) {
            if ((start2 - ip) < OPTIMAL_ML) {
                int correction;
                if (ml > OPTIMAL_ML) ml = OPTIMAL_ML;
                if (ip + ml > start2 + ml2 - MINMATCH) ml = (int)(start2 - ip) + ml2 - MINMATCH;
                correction = ml - (int)(start2 - ip);
                if (correction > 0) {
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                }
            } else {
                ml = (int)(start2 - ip);
            }
        }
        if (encodeSequence(&ip, &op, &anchor, ml, ref, limit, oend)) goto _dest_overflow;

        ip = start2; ref = ref2; ml = ml2;
        start2 = start3; ref2 = ref3; ml2 = ml3;
        goto _Search3;
    }

_last_literals:
    {
        size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit && (op + totalSize > oend)) return 0;
        ip = anchor + lastRunSize;
        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (uint8_t)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (uint8_t)accumulator;
        } else {
            *op++ = (uint8_t)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }
    *srcSizePtr = (int)(ip - source);
    return (int)(op - dest);

_dest_overflow:
    return 0;
}

/* ---------------- optimal parser ---------------- */
typedef struct { int price; int off; int mlen; int litlen; } optimal_t;
typedef struct { int off; int len; } match_t;

static inline int literalsPrice(int const litlen) {
    int price = litlen;
    if (litlen >= (int)RUN_MASK) price += 1 + ((litlen - (int)RUN_MASK) / 255);
    return price;
}
static inline int sequencePrice(int litlen, int mlen) {
    int price = 1 + 2;
    price += literalsPrice(litlen);
    if (mlen >= (int)(ML_MASK + MINMATCH)) price += 1 + ((mlen - (int)(ML_MASK + MINMATCH)) / 255);
    return price;
}

static match_t findLongerMatch(lz4hc_ctx* const ctx, const uint8_t* ip, const uint8_t* const iHighLimit,
                               int minLen, int nbSearches, const dictCtx_directive dict, const HCfavor_e favorDecSpeed)
{
    match_t match = { 0, 0 };
    const uint8_t* matchPtr = NULL;
    int matchLength = insertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen, &matchPtr, &ip, nbSearches, 1, 1, dict, favorDecSpeed);
    if (matchLength <= minLen) return match;
    if (favorDecSpeed) {
        if ((matchLength > 18) & (matchLength <= 36)) matchLength = 18;
    }
    match.len = matchLength;
    match.off = (int)(ip - matchPtr);
    return match;
}

#define TRAILING_LITERALS 3

static int compress_optimal(lz4hc_ctx* ctx, const uint8_t* const source, uint8_t* dst, int* srcSizePtr, int dstCapacity,
                            int const nbSearches, size_t sufficient_len, const limitedOutput_directive limit, int const fullUpdate,
                            const dictCtx_directive dict, const HCfavor_e favorDecSpeed)
{
    int retval = 0;
    optimal_t* const opt = (optimal_t*)malloc(sizeof(optimal_t) * (LZ4_OPT_NUM + TRAILING_LITERALS));
    const uint8_t* ip = source;
    const uint8_t* anchor = ip;
    const uint8_t* const iend = ip + *srcSizePtr;
    const uint8_t* const mflimit = iend - MFLIMIT;
    const uint8_t* const matchlimit = iend - LASTLITERALS;
    uint8_t* op = dst;
    uint8_t* oend = op + dstCapacity;

    if (opt == NULL) return 0;
    *srcSizePtr = 0;
    if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM - 1;

    while (ip <= mflimit) {
        int const llen = (int)(ip - anchor);
        int best_mlen, best_off;
        int cur, last_match_pos = 0;

        match_t const firstMatch = findLongerMatch(ctx, ip, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
        if (firstMatch.len == 0) { ip++; continue; }

        if ((size_t)firstMatch.len > sufficient_len) {
            int const firstML = firstMatch.len;
            const uint8_t* const matchPos = ip - firstMatch.off;
            if (encodeSequence(&ip, &op, &anchor, firstML, matchPos, limit, oend)) goto _dest_overflow;
            continue;
        }

        {
            int rPos;
            for (rPos = 0; rPos < MINMATCH; rPos++) {
                int const cost = literalsPrice(llen + rPos);
                opt[rPos].mlen = 1;
                opt[rPos].off = 0;
                opt[rPos].litlen = llen + rPos;
                opt[rPos].price = cost;
            }
        }
        {
            int mlen = MINMATCH;
            int const matchML = firstMatch.len;
            int const offset = firstMatch.off;
            for (; mlen <= matchML; mlen++) {
                int const cost = sequencePrice(llen, mlen);
                opt[mlen].mlen = mlen;
                opt[mlen].off = offset;
                opt[mlen].litlen = llen;
                opt[mlen].price = cost;
            }
        }
        last_match_pos = firstMatch.len;
        {
            int addLit;
            for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                opt[last_match_pos + addLit].mlen = 1;
                opt[last_match_pos + addLit].off = 0;
                opt[last_match_pos + addLit].litlen = addLit;
                opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
            }
        }

        for (cur = 1; cur < last_match_pos; cur++) {
            const uint8_t* const curPtr = ip + cur;
            match_t newMatch;

            if (curPtr > mflimit) break;
            if (fullUpdate) {
                if ((opt[cur + 1].price <= opt[cur].price)
                    && (opt[cur + MINMATCH].price < opt[cur].price + 3))
                    continue;
            } else {
                if (opt[cur + 1].price <= opt[cur].price) continue;
            }

            if (fullUpdate)
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
            else
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, last_match_pos - cur, nbSearches, dict, favorDecSpeed);
            if (!newMatch.len) continue;

            if (((size_t)newMatch.len > sufficient_len) || (newMatch.len + cur >= LZ4_OPT_NUM)) {
                best_mlen = newMatch.len;
                best_off = newMatch.off;
                last_match_pos = cur + 1;
                goto encode;
            }

            {
                int const baseLitlen = opt[cur].litlen;
                int litlen;
                for (litlen = 1; litlen < MINMATCH; litlen++) {
                    int const price = opt[cur].price - literalsPrice(baseLitlen) + literalsPrice(baseLitlen + litlen);
                    int const pos = cur + litlen;
                    if (price < opt[pos].price) {
                        opt[pos].mlen = 1;
                        opt[pos].off = 0;
                        opt[pos].litlen = baseLitlen + litlen;
                        opt[pos].price = price;
                    }
                }
            }

            {
                int const matchML = newMatch.len;
                int ml = MINMATCH;
                for (; ml <= matchML; ml++) {
                    int const pos = cur + ml;
                    int const offset = newMatch.off;
                    int price;
                    int ll;
                    if (opt[cur].mlen == 1) {
                        ll = opt[cur].litlen;
                        price = ((cur > ll) ? opt[cur - ll].price : 0) + sequencePrice(ll, ml);
                    } else {
                        ll = 0;
                        price = opt[cur].price + sequencePrice(0, ml);
                    }
                    if (pos > last_match_pos + TRAILING_LITERALS || price <= opt[pos].price - (int)favorDecSpeed) {
                        if ((ml == matchML) && (last_match_pos < pos)) last_match_pos = pos;
                        opt[pos].mlen = ml;
                        opt[pos].off = offset;
                        opt[pos].litlen = ll;
                        opt[pos].price = price;
                    }
                }
            }
            {
                int addLit;
                for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                    opt[last_match_pos + addLit].mlen = 1;
                    opt[last_match_pos + addLit].off = 0;
                    opt[last_match_pos + addLit].litlen = addLit;
                    opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
                }
            }
        }

        best_mlen = opt[last_match_pos].mlen;
        best_off = opt[last_match_pos].off;
        cur = last_match_pos - best_mlen;

encode:
        {
            int candidate_pos = cur;
            int selected_matchLength = best_mlen;
            int selected_offset = best_off;
            while (1) {
                int const next_matchLength = opt[candidate_pos].mlen;
                int const next_offset = opt[candidate_pos].off;
                opt[candidate_pos].mlen = selected_matchLength;
                opt[candidate_pos].off = selected_offset;
                selected_matchLength = next_matchLength;
                selected_offset = next_offset;
                if (next_matchLength > candidate_pos) break;
                candidate_pos -= next_matchLength;
            }
        }
        {
            int rPos = 0;
            while (rPos < last_match_pos) {
                int const ml = opt[rPos].mlen;
                int const offset = opt[rPos].off;
                if (ml == 1) { ip++; rPos++; continue; }
                rPos += ml;
                if (encodeSequence(&ip, &op, &anchor, ml, ip - offset, limit, oend)) goto _dest_overflow;
            }
        }
    }

    {
        size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit && (op + totalSize > oend)) { retval = 0; goto _return; }
        ip = anchor + lastRunSize;
        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (uint8_t)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (uint8_t)accumulator;
        } else {
            *op++ = (uint8_t)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }
    *srcSizePtr = (int)(ip - source);
    retval = (int)(op - dst);
    goto _return;

_dest_overflow:
    retval = 0;
_return:
    free(opt);
    return retval;
}

typedef enum { lz4hc, lz4opt } strat_e;
typedef struct { strat_e strat; int nbSearches; uint32_t targetLength; } cParams_t;
static const cParams_t clTable[LZ4HC_CLEVEL_MAX + 1] = {
    { lz4hc,     2, 16 },  /* 0, unused */
    { lz4hc,     2, 16 },  /* 1, unused */
    { lz4hc,     2, 16 },  /* 2 */
    { lz4hc,     4, 16 },  /* 3 */
    { lz4hc,     8, 16 },  /* 4 */
    { lz4hc,    16, 16 },  /* 5 */
    { lz4hc,    32, 16 },  /* 6 */
    { lz4hc,    64, 16 },  /* 7 */
    { lz4hc,   128, 16 },  /* 8 */
    { lz4hc,   256, 16 },  /* 9 */
    { lz4opt,   96, 64 },  /* 10 */
    { lz4opt,  512, 128 }, /* 11 */
    { lz4opt, 16384, LZ4_OPT_NUM },  /* 12 */
};

static int compress_generic_internal(lz4hc_ctx* const ctx, const uint8_t* const src, uint8_t* const dst, int* const srcSizePtr,
                                     int const dstCapacity, int cLevel, const limitedOutput_directive limit, const dictCtx_directive dict)
{
    if ((uint32_t)*srcSizePtr > 0x7E000000) return 0;
    ctx->end += *srcSizePtr;
    if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;
    cLevel = MIN(LZ4HC_CLEVEL_MAX, cLevel);
    {
        cParams_t const cParam = clTable[cLevel];
        HCfavor_e const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
        int result;
        if (cParam.strat == lz4hc) {
            result = compress_hashChain(ctx, src, dst, srcSizePtr, dstCapacity, cParam.nbSearches, limit, dict);
        } else {
            result = compress_optimal(ctx, src, dst, srcSizePtr, dstCapacity, cParam.nbSearches, cParam.targetLength, limit,
                                      cLevel == LZ4HC_CLEVEL_MAX, dict, favor);
        }
        if (result <= 0) ctx->dirty = 1;
        return result;
    }
}

static void setExternalDict(lz4hc_ctx* ctxPtr, const uint8_t* newBlock) {
    if (ctxPtr->end >= ctxPtr->prefixStart + 4) hcInsert(ctxPtr, ctxPtr->end - 3);
    ctxPtr->lowLimit = ctxPtr->dictLimit;
    ctxPtr->dictStart = ctxPtr->prefixStart;
    ctxPtr->dictLimit += (uint32_t)(ctxPtr->end - ctxPtr->prefixStart);
    ctxPtr->prefixStart = newBlock;
    ctxPtr->end = newBlock;
    ctxPtr->nextToUpdate = ctxPtr->dictLimit;
    ctxPtr->dictCtx = NULL;
}

static int compress_generic_noDictCtx(lz4hc_ctx* const ctx, const uint8_t* const src, uint8_t* const dst, int* const srcSizePtr,
                                      int const dstCapacity, int cLevel, limitedOutput_directive limit) {
    return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, noDictCtx);
}

static int compress_generic_dictCtx(lz4hc_ctx* const ctx, const uint8_t* const src, uint8_t* const dst, int* const srcSizePtr,
                                    int const dstCapacity, int cLevel, limitedOutput_directive limit) {
    const size_t position = (size_t)(ctx->end - ctx->prefixStart) + (ctx->dictLimit - ctx->lowLimit);
    if (position >= 64 KB) {
        ctx->dictCtx = NULL;
        return compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else if (position == 0 && *srcSizePtr > 4 KB) {
        memcpy(ctx, ctx->dictCtx, sizeof(lz4hc_ctx));
        setExternalDict(ctx, src);
        ctx->compressionLevel = (short)cLevel;
        return compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    } else {
        return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, usingDictCtxHc);
    }
}

static int compress_generic(lz4hc_ctx* const ctx, const uint8_t* const src, uint8_t* const dst, int* const srcSizePtr,
                            int const dstCapacity, int cLevel, limitedOutput_directive limit) {
    if (ctx->dictCtx == NULL) return compress_generic_noDictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
    return compress_generic_dictCtx(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit);
}

static int compressBound(int isize) { return (isize > 0x7E000000) ? 0 : isize + (isize / 255) + 16; }

int lz4hc_compress_extState_fastReset(lz4hc_ctx* ctx, const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity, int compressionLevel)
{
    lz4hc_resetStream_fast(ctx, compressionLevel);
    init_internal(ctx, src);
    if (dstCapacity < compressBound(srcSize))
        return compress_generic(ctx, src, dst, &srcSize, dstCapacity, compressionLevel, limitedOutput);
    return compress_generic(ctx, src, dst, &srcSize, dstCapacity, compressionLevel, notLimited);
}

int lz4hc_loadDict(lz4hc_ctx* ctxPtr, const uint8_t* dictionary, int dictSize)
{
    if (dictSize > 64 KB) {
        dictionary += (size_t)dictSize - 64 KB;
        dictSize = 64 KB;
    }
    {
        int const cLevel = ctxPtr->compressionLevel;
        lz4hc_initStream(ctxPtr);
        lz4hc_setCompressionLevel(ctxPtr, cLevel);
    }
    init_internal(ctxPtr, dictionary);
    ctxPtr->end = dictionary + dictSize;
    if (dictSize >= 4) hcInsert(ctxPtr, ctxPtr->end - 3);
    return dictSize;
}

void lz4hc_attach_dictionary(lz4hc_ctx* working, const lz4hc_ctx* dict)
{
    if (dict != NULL) {
        if (working->prefixStart == NULL) init_internal(working, NULL);
        working->dictCtx = dict;
    } else {
        working->dictCtx = NULL;
    }
}

int lz4hc_compress_continue(lz4hc_ctx* ctxPtr, const uint8_t* src, uint8_t* dst, int srcSize, int dstCapacity)
{
    limitedOutput_directive limit = (dstCapacity < compressBound(srcSize)) ? limitedOutput : notLimited;
    if (ctxPtr->prefixStart == NULL) init_internal(ctxPtr, src);

    if ((size_t)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit > 2 GB) {
        size_t dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
        if (dictSize > 64 KB) dictSize = 64 KB;
        lz4hc_loadDict(ctxPtr, ctxPtr->end - dictSize, (int)dictSize);
    }

    if (src != ctxPtr->end) setExternalDict(ctxPtr, src);

    {
        const uint8_t* sourceEnd = src + srcSize;
        const uint8_t* const dictBegin = ctxPtr->dictStart;
