#include "lz4b.h"
#include "lz4hc.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static uint8_t* readfile(const char* n, long* sz) { FILE* f = fopen(n, "rb"); fseek(f, 0, SEEK_END); *sz = ftell(f); fseek(f, 0, SEEK_SET); uint8_t* b = malloc(*sz + 1); if (fread(b, 1, *sz, f) != (size_t)*sz) exit(1); fclose(f); return b; }
int main(int argc, char** argv) {
    long sz, dsz;
    uint8_t* buf = readfile(argv[1], &sz);
    uint8_t* dict = readfile(argv[2], &dsz);
    int level = atoi(argv[3]);
    long blockSize = atol(argv[4]);
    int mode = atoi(argv[5]); /* 0: ext layout (dict separate), 1: prefix layout (dict copied before block) */
    int bd = argc > 6 ? atoi(argv[6]) : 0;
    uint8_t* out = malloc(blockSize + blockSize / 255 + 16);
    uint8_t* work = malloc(65536 + 4194304);
    lz4b_stream* s = calloc(1, sizeof(lz4b_stream));
    lz4hc_ctx* h = calloc(1, sizeof(lz4hc_ctx));
    long chunkSize = 4194304;
    for (long cp = 0; cp < sz; cp += chunkSize) {
        long cn = (sz - cp) < chunkSize ? (sz - cp) : chunkSize;
        const uint8_t* dptr; long dlen;
        if (cp == 0 || !bd) { dptr = dict; dlen = dsz; } else { dptr = buf + cp - 65536; dlen = 65536; }
        if (dlen > 65536) { dptr += dlen - 65536; dlen = 65536; }
        const uint8_t* src;
        if (mode == 1) { memcpy(work, dptr, dlen); memcpy(work + dlen, buf + cp, cn); dptr = work; src = work + dlen; }
        else src = buf + cp;
        if (level < 2) {
            lz4b_resetStream(s);
            if (dlen) lz4b_loadDict(s, dptr, (int)dlen);
        } else {
            lz4hc_initStream(h); lz4hc_setCompressionLevel(h, level);
            if (dlen) lz4hc_loadDict(h, dptr, (int)dlen);
        }
        for (long p = 0; p < cn; p += blockSize) {
            int n = (cn - p) < blockSize ? (int)(cn - p) : (int)blockSize;
            int c;
            if (!bd && p > 0) { /* independent blocks: reload dict for each block */
                if (level < 2) { lz4b_resetStream(s); if (dlen) lz4b_loadDict(s, dptr, (int)dlen); }
                else { lz4hc_initStream(h); lz4hc_setCompressionLevel(h, level); if (dlen) lz4hc_loadDict(h, dptr, (int)dlen); }
            }
            if (level < 2) c = lz4b_compress_fast_continue(s, src + p, out, n, (int)(blockSize + blockSize / 255 + 16), 1);
            else c = lz4hc_compress_continue(h, src + p, out, n, (int)(blockSize + blockSize / 255 + 16));
            fwrite(out, 1, c, stdout);
        }
    }
    return 0;
}
