cat > /workspace/src/xxh32.c <<'EOF'
#include "xxh32.h"
#include <string.h>

#define P1 2654435761U
#define P2 2246822519U
#define P3 3266489917U
#define P4 668265263U
#define P5 374761393U

static inline uint32_t rd32(const void* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline uint32_t rotl(uint32_t x, int r) { return (x << r) | (x >> (32 - r)); }
static inline uint32_t round32(uint32_t acc, uint32_t input) { acc += input * P2; acc = rotl(acc, 13); acc *= P1; return acc; }

static uint32_t avalanche(uint32_t h) {
    h ^= h >> 15; h *= P2; h ^= h >> 13; h *= P3; h ^= h >> 16; return h;
}

static uint32_t finalize(uint32_t h, const uint8_t* p, size_t len) {
    len &= 15;
    while (len >= 4) { h += rd32(p) * P3; p += 4; h = rotl(h, 17) * P4; len -= 4; }
    while (len > 0) { h += (*p++) * P5; h = rotl(h, 11) * P1; len--; }
    return avalanche(h);
}

uint32_t xxh32(const void* input, size_t len, uint32_t seed) {
    const uint8_t* p = (const uint8_t*)input;
    const uint8_t* const end = p + len;
    uint32_t h;
    if (len >= 16) {
        const uint8_t* const limit = end - 15;
        uint32_t v1 = seed + P1 + P2, v2 = seed + P2, v3 = seed, v4 = seed - P1;
        do {
            v1 = round32(v1, rd32(p)); p += 4;
            v2 = round32(v2, rd32(p)); p += 4;
            v3 = round32(v3, rd32(p)); p += 4;
            v4 = round32(v4, rd32(p)); p += 4;
        } while (p < limit);
        h = rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18);
    } else {
        h = seed + P5;
    }
    h += (uint32_t)len;
    return finalize(h, p, len);
}

void xxh32_reset(xxh32_state* st, uint32_t seed) {
    memset(st, 0, sizeof(*st));
    st->v[0] = seed + P1 + P2; st->v[1] = seed + P2; st->v[2] = seed; st->v[3] = seed - P1;
}

void xxh32_update(xxh32_state* st, const void* input, size_t len) {
    const uint8_t* p = (const uint8_t*)input;
    const uint8_t* const end = p + len;
    st->total_len_32 += (uint32_t)len;
    st->large_len |= (len >= 16) | (st->total_len_32 >= 16);
    if (st->memsize + len < 16) {
        memcpy((uint8_t*)st->mem32 + st->memsize, input, len);
        st->memsize += (uint32_t)len;
        return;
    }
    if (st->memsize) {
        memcpy((uint8_t*)st->mem32 + st->memsize, input, 16 - st->memsize);
        st->v[0] = round32(st->v[0], st->mem32[0]);
        st->v[1] = round32(st->v[1], st->mem32[1]);
        st->v[2] = round32(st->v[2], st->mem32[2]);
        st->v[3] = round32(st->v[3], st->mem32[3]);
        p += 16 - st->memsize;
        st->memsize = 0;
    }
    if (p <= end - 16) {
        const uint8_t* const limit = end - 16;
        uint32_t v1 = st->v[0], v2 = st->v[1], v3 = st->v[2], v4 = st->v[3];
        do {
            v1 = round32(v1, rd32(p)); p += 4;
            v2 = round32(v2, rd32(p)); p += 4;
            v3 = round32(v3, rd32(p)); p += 4;
            v4 = round32(v4, rd32(p)); p += 4;
        } while (p <= limit);
        st->v[0] = v1; st->v[1] = v2; st->v[2] = v3; st->v[3] = v4;
    }
    if (p < end) {
        memcpy(st->mem32, p, (size_t)(end - p));
        st->memsize = (uint32_t)(end - p);
    }
}

uint32_t xxh32_digest(const xxh32_state* st) {
    uint32_t h;
    if (st->large_len) h = rotl(st->v[0], 1) + rotl(st->v[1], 7) + rotl(st->v[2], 12) + rotl(st->v[3], 18);
    else h = st->v[2] /* == seed */ + P5;
    h += st->total_len_32;
    return finalize(h, (const uint8_t*)st->mem32, st->memsize);
}
