static void* malloc_or_die(size_t s) { void* p = malloc(s ? s : 1); if (!p) EXM_THROW(21, "Allocation error : not enough memory"); return p; }
static void* calloc_or_die(size_t s) { void* p = calloc(1, s ? s : 1); if (!p) EXM_THROW(21, "Allocation error : not enough memory"); return p; }

/* ---------- preferences ---------- */
