/* ---------- dictionary ---------- */
typedef struct {
    uint8_t* content;     /* last 64 KB (at most) of the dictionary file */
    int size;
    lz4b_stream* fastCtx; /* loaded with every position */
    lz4hc_ctx* hcCtx;     /* loaded at default HC level */
} cdict_t;

static cdict_t* createCDict(const lz4io_prefs* prefs)
{
    cdict_t* d;
    FILE* f;
    uint8_t* buf;
    size_t total = 0, cap = 64 KB + 1;
    if (prefs->dictionaryFilename == NULL) return NULL;
    f = openSrcFile(prefs->dictionaryFilename);
    if (f == NULL) EXM_THROW(27, "Dictionary error : could not open dictionary file");
    /* keep only the last 64 KB, circularly */
    buf = (uint8_t*)malloc_or_die(2 * (64 KB));
    {
        size_t used = 0;
        for (;;) {
            size_t r = fread(buf + used, 1, 64 KB, f);
            used += r; total += r;
            if (used > 64 KB) { memmove(buf, buf + used - 64 KB, 64 KB); used = 64 KB; }
            if (r == 0) break;
        }
        d = (cdict_t*)calloc_or_die(sizeof(cdict_t));
        d->size = (int)used;
        d->content = (uint8_t*)malloc_or_die(used + 8);
        memcpy(d->content, buf, used);
    }
