typedef struct {
    int level;
    int acceleration;
    lz4b_stream* fast;
    lz4hc_ctx* hc;
    int favorDecSpeed;
} cctx_t;

static cctx_t* createCCtx(int level, int favorDecSpeed)
{
    cctx_t* c = (cctx_t*)calloc_or_die(sizeof(cctx_t));
    c->level = level;
    c->acceleration = (level < 0) ? -level + 1 : 1;
    c->favorDecSpeed = favorDecSpeed;
    c->fast = (lz4b_stream*)calloc_or_die(sizeof(lz4b_stream));
    c->hc = (lz4hc_ctx*)calloc_or_die(sizeof(lz4hc_ctx));
    lz4hc_initStream(c->hc);
    lz4hc_setCompressionLevel(c->hc, level);
    lz4hc_favorDecompressionSpeed(c->hc, favorDecSpeed);
