cat > /workspace/src/lz4io.c <<'EOF'
/* File-level operations: frame/legacy compression and decompression, listing. */
#define _GNU_SOURCE
#include "lz4io.h"
#include "lz4b.h"
#include "lz4hc.h"
#include "xxh32.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <errno.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <utime.h>

int g_displayLevel = 2;
const char* g_programName = "lz4";
const char* const lz4io_stdinmark = "stdin";
const char* const lz4io_stdoutmark = "stdout";
const char* const lz4io_nullmark = "null";

#define KB *(1 << 10)
#define MB *(1 << 20)
#define GB *(1U << 30)

#define DISPLAY(...) fprintf(stderr, __VA_ARGS__)
#define DISPLAYLEVEL(l, ...) do { if (g_displayLevel >= (l)) DISPLAY(__VA_ARGS__); } while (0)
#define DISPLAYOUT(...) fprintf(stdout, __VA_ARGS__)

static double g_lastUpdate = -1.0;   /* wall-clock time of last progress display */
static const double refreshRate = 1.0 / 6.0;
static double nowSec(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9; }
#define DISPLAYUPDATE(l, ...) do { if (g_displayLevel >= (l)) { double t = nowSec(); \
    if ((g_lastUpdate < 0) || (t - g_lastUpdate > refreshRate) || (g_displayLevel >= 4)) { g_lastUpdate = t; DISPLAY(__VA_ARGS__); if (g_displayLevel >= 4) fflush(stderr); } } } while (0)

void lz4io_error(int code, const char* fmt, ...)
{
    va_list ap;
    DISPLAYLEVEL(1, "Error %i : ", code);
    if (g_displayLevel >= 1) { va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap); }
    DISPLAYLEVEL(1, " \n");
    exit(code);
}
#define EXM_THROW(code, ...) lz4io_error(code, __VA_ARGS__)

static void* malloc_or_die(size_t s) { void* p = malloc(s ? s : 1); if (!p) EXM_THROW(21, "Allocation error : not enough memory"); return p; }
static void* calloc_or_die(size_t s) { void* p = calloc(1, s ? s : 1); if (!p) EXM_THROW(21, "Allocation error : not enough memory"); return p; }

/* ---------- preferences ---------- */
void lz4io_defaultPrefs(lz4io_prefs* p)
{
    memset(p, 0, sizeof(*p));
    p->compressionLevel = 1;
    p->blockSizeId = 7;
    p->blockSize = 4 MB;
    p->blockIndependence = 1;
    p->blockChecksum = 0;
    p->streamChecksum = 1;
    p->contentSizeFlag = 0;
    p->favorDecSpeed = 0;
    p->useLegacyFormat = 0;
    p->overwrite = 1;
    p->testMode = 0;
    p->removeSrcFile = 0;
    p->sparseFileSupport = 1;
    p->passThrough = 0;
    p->nbWorkers = 0;
    p->dictionaryFilename = NULL;
}

static const int blockSizeTable[4] = { 64 KB, 256 KB, 1 MB, 4 MB };
static int blockSizeFromId(int id) { return blockSizeTable[id - 4]; }

int lz4io_setBlockSizeID(lz4io_prefs* p, unsigned id)
{
    if (id < 4 || id > 7) return 0;
    p->blockSizeId = (int)id;
    p->blockSize = blockSizeFromId((int)id);
    return p->blockSize;
}

int lz4io_setBlockSize(lz4io_prefs* p, size_t blockSize)
{
    unsigned id = 4;
    size_t s = 64 KB;
    while (id < 7 && blockSize > s) { id++; s <<= 2; }
    return lz4io_setBlockSizeID(p, id);
}

/* ---------- small utils ---------- */
static void writeLE32(void* p, uint32_t v) { uint8_t* b = (uint8_t*)p; b[0] = (uint8_t)v; b[1] = (uint8_t)(v >> 8); b[2] = (uint8_t)(v >> 16); b[3] = (uint8_t)(v >> 24); }
static void writeLE64(void* p, uint64_t v) { writeLE32(p, (uint32_t)v); writeLE32((uint8_t*)p + 4, (uint32_t)(v >> 32)); }
static uint32_t readLE32(const void* p) { const uint8_t* b = (const uint8_t*)p; return (uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24); }
static uint64_t readLE64(const void* p) { return (uint64_t)readLE32(p) | ((uint64_t)readLE32((const uint8_t*)p + 4) << 32); }

static int isDirectory(const char* name) { struct stat st; if (stat(name, &st) != 0) return 0; return S_ISDIR(st.st_mode); }
static int isRegFile(const char* name) { struct stat st; if (stat(name, &st) != 0) return 0; return S_ISREG(st.st_mode); }
static uint64_t getFileSize(const char* name) { struct stat st; if (stat(name, &st) != 0) return 0; if (!S_ISREG(st.st_mode)) return 0; return (uint64_t)st.st_size; }

static int setFileStat(const char* filename, const struct stat* st)
{
    int res = 0;
    struct utimbuf timebuf;
    timebuf.actime = st->st_atime;
    timebuf.modtime = st->st_mtime;
    res += utime(filename, &timebuf);
    res += chown(filename, st->st_uid, st->st_gid);
    res += chmod(filename, st->st_mode & 0777);
    errno = 0;
    return -res;
}

static FILE* openSrcFile(const char* srcFileName)
{
    FILE* f;
    if (!strcmp(srcFileName, lz4io_stdinmark)) {
        DISPLAYLEVEL(4, "Using stdin for input \n");
        f = stdin;
    } else {
        f = fopen(srcFileName, "rb");
        if (f == NULL) DISPLAYLEVEL(1, "%s: %s \n", srcFileName, strerror(errno));
    }
    return f;
}

static FILE* openDstFile(const char* dstFileName, const lz4io_prefs* prefs)
{
    FILE* f;
    if (!strcmp(dstFileName, lz4io_stdoutmark)) {
        DISPLAYLEVEL(4, "Using stdout for output \n");
        f = stdout;
        if (prefs->sparseFileSupport == 1) {
            DISPLAYLEVEL(4, "Sparse File Support automatically disabled on stdout ; to force-enable it, add --sparse command \n");
        }
    } else {
        if (!prefs->overwrite && strcmp(dstFileName, lz4io_nullmark)) {
            FILE* const testf = fopen(dstFileName, "rb");
            if (testf != NULL) {
                fclose(testf);
                if (g_displayLevel <= 1) {
                    DISPLAY("%s already exists; not overwritten  \n", dstFileName);
                    return NULL;
                }
                DISPLAY("%s already exists; do you want to overwrite (y/N) ? ", dstFileName);
                {
                    int ch = getchar();
                    if ((ch != 'Y') && (ch != 'y')) {
                        DISPLAY("    not overwritten  \n");
                        return NULL;
                    }
                    while ((ch != EOF) && (ch != '\n')) ch = getchar();
                }
            }
        }
        f = fopen(dstFileName, "wb");
        if (f == NULL) DISPLAYLEVEL(1, "%s: %s\n", dstFileName, strerror(errno));
    }
    return f;
}

/* ---------- dictionary ---------- */
typedef struct {
    uint8_t* content;     /* last 64 KB (at most) of the dictionary file */
    int size;
    lz4b_stream* fastCtx; /* loaded with every position */
    lz4hc_ctx* hcCtx;     /* loaded at default HC level */
} cdict_t;

static cdict_t* createCDict(const lz4io_prefs* prefs)
{
    cdict_t* d;
    FILE* f;
    uint8_t* buf;
    size_t total = 0, cap = 64 KB + 1;
    if (prefs->dictionaryFilename == NULL) return NULL;
    f = openSrcFile(prefs->dictionaryFilename);
    if (f == NULL) EXM_THROW(27, "Dictionary error : could not open dictionary file");
    /* keep only the last 64 KB, circularly */
    buf = (uint8_t*)malloc_or_die(2 * (64 KB));
    {
        size_t used = 0;
        for (;;) {
            size_t r = fread(buf + used, 1, 64 KB, f);
            used += r; total += r;
            if (used > 64 KB) { memmove(buf, buf + used - 64 KB, 64 KB); used = 64 KB; }
            if (r == 0) break;
        }
        d = (cdict_t*)calloc_or_die(sizeof(cdict_t));
        d->size = (int)used;
        d->content = (uint8_t*)malloc_or_die(used + 8);
        memcpy(d->content, buf, used);
    }
    (void)cap;
    free(buf);
    if (f != stdin) fclose(f);
    d->fastCtx = (lz4b_stream*)calloc_or_die(sizeof(lz4b_stream));
    lz4b_loadDictSlow(d->fastCtx, d->content, d->size);
    d->hcCtx = (lz4hc_ctx*)calloc_or_die(sizeof(lz4hc_ctx));
    lz4hc_initStream(d->hcCtx);
    lz4hc_setCompressionLevel(d->hcCtx, LZ4HC_CLEVEL_DEFAULT);
    lz4hc_loadDict(d->hcCtx, d->content, d->size);
    return d;
}

static void freeCDict(cdict_t* d)
{
    if (!d) return;
    free(d->content); free(d->fastCtx); free(d->hcCtx); free(d);
}

/* ---------- block compression engine ---------- */
typedef struct {
    int level;
    int acceleration;
    lz4b_stream* fast;
    lz4hc_ctx* hc;
    int favorDecSpeed;
} cctx_t;

static cctx_t* createCCtx(int level, int favorDecSpeed)
{
    cctx_t* c = (cctx_t*)calloc_or_die(sizeof(cctx_t));
    c->level = level;
    c->acceleration = (level < 0) ? -level + 1 : 1;
    c->favorDecSpeed = favorDecSpeed;
    c->fast = (lz4b_stream*)calloc_or_die(sizeof(lz4b_stream));
    c->hc = (lz4hc_ctx*)calloc_or_die(sizeof(lz4hc_ctx));
    lz4hc_initStream(c->hc);
    lz4hc_setCompressionLevel(c->hc, level);
    lz4hc_favorDecompressionSpeed(c->hc, favorDecSpeed);
    return c;
}
static void freeCCtx(cctx_t* c) { if (!c) return; free(c->fast); free(c->hc); free(c); }
static int isHC(int level) { return level >= LZ4HC_CLEVEL_MIN; }

/* reset context for a fresh stream (no history) */
static void cctxReset(cctx_t* c)
{
    lz4b_resetStream(c->fast);
    lz4hc_initStream(c->hc);
    lz4hc_setCompressionLevel(c->hc, c->level);
    lz4hc_favorDecompressionSpeed(c->hc, c->favorDecSpeed);
}

/* independent block */
static int compressBlockIndependent(cctx_t* c, const cdict_t* cd, const uint8_t* src, int srcSize, uint8_t* dst, int dstCapacity)
{
    if (cd) {
        if (isHC(c->level)) {
            lz4hc_initStream(c->hc);
            lz4hc_setCompressionLevel(c->hc, c->level);
            lz4hc_favorDecompressionSpeed(c->hc, c->favorDecSpeed);
            return lz4hc_compress_usingDictCtx(c->hc, cd->hcCtx, c->level, src, dst, srcSize, dstCapacity);
        }
        lz4b_resetStream(c->fast);
        lz4b_attach_dictionary(c->fast, cd->fastCtx);
        return lz4b_compress_fast_continue(c->fast, src, dst, srcSize, dstCapacity, c->acceleration);
    }
    if (isHC(c->level)) {
        lz4hc_initStream(c->hc);
        lz4hc_setCompressionLevel(c->hc, c->level);
        lz4hc_favorDecompressionSpeed(c->hc, c->favorDecSpeed);
        return lz4hc_compress_extState_fastReset(c->hc, src, dst, srcSize, dstCapacity, c->level);
    }
    lz4b_resetStream(c->fast);
    return lz4b_compress_fast_extState_fastReset(c->fast, src, dst, srcSize, dstCapacity, c->acceleration);
}

/* start a linked stream: optional prefix dictionary (contiguous before src) or cdict */
static void cctxStartStream(cctx_t* c, const cdict_t* cd, const uint8_t* prefix, int prefixSize)
{
    cctxReset(c);
    if (prefix && prefixSize > 0) {
        if (isHC(c->level)) lz4hc_loadDict(c->hc, prefix, prefixSize);
        else lz4b_loadDict(c->fast, prefix, prefixSize);
    } else if (cd) {
        if (isHC(c->level)) lz4hc_attach_dictionary(c->hc, cd->hcCtx);
        else lz4b_attach_dictionary(c->fast, cd->fastCtx);
    }
}

static int compressBlockContinue(cctx_t* c, const uint8_t* src, int srcSize, uint8_t* dst, int dstCapacity)
{
    if (isHC(c->level)) return lz4hc_compress_continue(c->hc, src, dst, srcSize, dstCapacity);
    return lz4b_compress_fast_continue(c->fast, src, dst, srcSize, dstCapacity, c->acceleration);
}

/* ---------- frame header ---------- */
typedef struct {
    int blockSizeId;
    int blockIndependent;
    int blockChecksum;
    int contentChecksum;
    uint64_t contentSize;   /* 0 = not present */
    int contentSizeFlag;
} frameInfo_t;

static size_t writeFrameHeader(uint8_t* dst, const frameInfo_t* fi)
{
    uint8_t* p = dst;
    uint8_t flg;
    writeLE32(p, LZ4IO_MAGICNUMBER); p += 4;
    flg = (uint8_t)((1 << 6) | ((fi->blockIndependent ? 1 : 0) << 5) | ((fi->blockChecksum ? 1 : 0) << 4)
                    | ((fi->contentSizeFlag ? 1 : 0) << 3) | ((fi->contentChecksum ? 1 : 0) << 2));
    *p++ = flg;
    *p++ = (uint8_t)(fi->blockSizeId << 4);
    if (fi->contentSizeFlag) { writeLE64(p, fi->contentSize); p += 8; }
    *p = (uint8_t)((xxh32(dst + 4, (size_t)(p - (dst + 4)), 0) >> 8) & 0xFF);
    p++;
    return (size_t)(p - dst);
}

/* write one block (compressed or stored) into dst; returns bytes written */
static size_t makeBlock(uint8_t* dst, const uint8_t* src, int srcSize, int cSize, int blockChecksum)
{
    size_t total;
    if (cSize == 0 || cSize >= srcSize) {
        /* stored */
        writeLE32(dst, (uint32_t)srcSize | 0x80000000U);
        memcpy(dst + 4, src, (size_t)srcSize);
        cSize = srcSize;
    } else {
        writeLE32(dst, (uint32_t)cSize);
    }
    total = 4 + (size_t)cSize;
    if (blockChecksum) { writeLE32(dst + total, xxh32(dst + 4, (size_t)cSize, 0)); total += 4; }
    return total;
}

static int optimalBSID(int requested, uint64_t srcSize)
{
    int proposed = 4;
    uint64_t maxBlockSize = 64 KB;
    while (requested > proposed) {
        if (srcSize <= maxBlockSize) return proposed;
        proposed++;
        maxBlockSize <<= 2;
    }
    return requested;
}

/* ---------- compression resources ---------- */
typedef struct {
    uint8_t* srcBuffer;       /* 64 KB prefix + chunk */
    size_t srcBufferSize;
    uint8_t* dstBuffer;
    size_t dstBufferSize;
    cctx_t* cctx;
    cdict_t* cdict;
    uint64_t totalInSize;
} cRess_t;

static size_t compressBound(size_t s) { return s + s / 255 + 16; }

static cRess_t createCResources(const lz4io_prefs* prefs)
{
    cRess_t r;
    memset(&r, 0, sizeof(r));
    r.srcBufferSize = 64 KB + LZ4IO_CHUNKSIZE + 8;
    r.srcBuffer = (uint8_t*)malloc_or_die(r.srcBufferSize);
    /* worst case: chunk split in blocks, each with header + checksum */
    r.dstBufferSize = compressBound(LZ4IO_CHUNKSIZE) + 64 * 8 + 64;
    r.dstBuffer = (uint8_t*)malloc_or_die(r.dstBufferSize);
    r.cctx = createCCtx(prefs->compressionLevel, prefs->favorDecSpeed);
    r.cdict = createCDict(prefs);
    return r;
}

static void freeCResources(cRess_t* r)
{
    free(r->srcBuffer); free(r->dstBuffer); freeCCtx(r->cctx); freeCDict(r->cdict);
}

/* compress a chunk (sequence of blocks). dictionary handling:
 *  - independent blocks: each block uses cdict (if any)
 *  - linked blocks: stream starts with prefix (previous data, contiguous before src) if prefixSize>0, else cdict.
 * Returns the number of bytes written to dst. */
static size_t compressChunk(cRess_t* ress, const uint8_t* src, size_t srcSize, int prefixSize,
                            uint8_t* dst, int blockSize, int blockIndependent, int blockChecksum)
{
    size_t pos = 0;
    uint8_t* op = dst;
    cctx_t* c = ress->cctx;
    if (!blockIndependent) cctxStartStream(c, ress->cdict, src - prefixSize, prefixSize);
    while (pos < srcSize) {
        int const n = (srcSize - pos) < (size_t)blockSize ? (int)(srcSize - pos) : blockSize;
        int cSize;
        uint8_t* const blockOut = op + 4;
        if (blockIndependent) cSize = compressBlockIndependent(c, ress->cdict, src + pos, n, blockOut, (int)compressBound((size_t)n));
        else cSize = compressBlockContinue(c, src + pos, n, blockOut, (int)compressBound((size_t)n));
        op += makeBlock(op, src + pos, n, cSize, blockChecksum);
        pos += (size_t)n;
    }
    return (size_t)(op - dst);
}

/* ---------- legacy format ---------- */
static int compressLegacy(cRess_t* ress, FILE* finput, FILE* foutput, const lz4io_prefs* prefs,
                          uint64_t* filesizePtr, uint64_t* compressedfilesizePtr)
{
    uint64_t filesize = 0, compressedfilesize = 4;
    uint8_t* in_buff = (uint8_t*)malloc_or_die(LEGACY_BLOCKSIZE);
    uint8_t* out_buff = (uint8_t*)malloc_or_die(compressBound(LEGACY_BLOCKSIZE) + 4);
    uint8_t magic[4];
    writeLE32(magic, LEGACY_MAGICNUMBER);
    if (fwrite(magic, 1, 4, foutput) != 4) EXM_THROW(38, "Write error : cannot write header");
    (void)prefs;
    for (;;) {
        size_t inSize = fread(in_buff, 1, LEGACY_BLOCKSIZE, finput);
        int outSize;
        if (inSize == 0) break;
        filesize += inSize;
        outSize = compressBlockIndependent(ress->cctx, NULL, in_buff, (int)inSize, out_buff + 4, (int)compressBound(inSize));
        if (outSize <= 0) EXM_THROW(36, "Compression error");
        compressedfilesize += (uint64_t)outSize + 4;
        DISPLAYUPDATE(2, "\rRead : %i MiB  ==> %.2f%%   ", (int)(filesize >> 20), (double)compressedfilesize / (double)filesize * 100);
        writeLE32(out_buff, (uint32_t)outSize);
        if (fwrite(out_buff, 1, (size_t)outSize + 4, foutput) != (size_t)outSize + 4) EXM_THROW(38, "Write error : cannot write compressed block");
    }
    if (ferror(finput)) EXM_THROW(39, "Error reading %s ", "input");
    free(in_buff); free(out_buff);
    *filesizePtr = filesize;
    *compressedfilesizePtr = compressedfilesize;
    return 0;
}

/* ---------- main compression routine ---------- */
static int compressFilename_extRess(cRess_t* ress, const char* srcFileName, const char* dstFileName, const lz4io_prefs* prefs)
{
    FILE* finput;
    FILE* foutput;
    uint64_t filesize = 0;
    uint64_t compressedfilesize = 0;
    struct stat statbuf;
    int hasStat = 0;

    if (isDirectory(srcFileName)) {
        DISPLAYLEVEL(1, "lz4: %s is a directory -- ignored \n", srcFileName);
        return 1;
    }
    finput = openSrcFile(srcFileName);
    if (finput == NULL) return 1;
    foutput = openDstFile(dstFileName, prefs);
    if (foutput == NULL) { if (finput != stdin) fclose(finput); return 1; }
    if (strcmp(srcFileName, lz4io_stdinmark) && stat(srcFileName, &statbuf) == 0) hasStat = 1;

    if (prefs->useLegacyFormat) {
        compressLegacy(ress, finput, foutput, prefs, &filesize, &compressedfilesize);
    } else {
        frameInfo_t fi;
        int const blockSize = prefs->blockSize;
        uint8_t* const src = ress->srcBuffer + 64 KB;
        size_t readSize;
        xxh32_state xxh;
        uint8_t header[32];
        size_t headerSize;

        memset(&fi, 0, sizeof(fi));
        fi.blockSizeId = prefs->blockSizeId;
        fi.blockIndependent = prefs->blockIndependence;
        fi.blockChecksum = prefs->blockChecksum;
        fi.contentChecksum = prefs->streamChecksum;
        fi.contentSizeFlag = prefs->contentSizeFlag;
        if (fi.contentSizeFlag) {
            uint64_t const fs = strcmp(srcFileName, lz4io_stdinmark) ? getFileSize(srcFileName) : 0;
            /* stdin redirected from a regular file is also acceptable */
            if (!strcmp(srcFileName, lz4io_stdinmark)) {
                struct stat sb;
                if (fstat(fileno(stdin), &sb) == 0 && S_ISREG(sb.st_mode)) fi.contentSize = (uint64_t)sb.st_size;
            } else fi.contentSize = fs;
            if (fi.contentSize == 0) fi.contentSizeFlag = 0;
        }
        xxh32_reset(&xxh, 0);

        readSize = fread(src, 1, LZ4IO_CHUNKSIZE, finput);
        if (ferror(finput)) EXM_THROW(30, "Error reading %s ", srcFileName);
        filesize += readSize;

        if (readSize < LZ4IO_CHUNKSIZE) {
            /* single chunk: whole content known */
            size_t cSize;
            int bsid = optimalBSID(fi.blockSizeId, readSize);
            int bs = blockSizeFromId(bsid);
            fi.blockSizeId = bsid;
            if (readSize <= (size_t)bs) fi.blockIndependent = 1;
            if (fi.contentSizeFlag) fi.contentSize = readSize;
            headerSize = writeFrameHeader(ress->dstBuffer, &fi);
            cSize = headerSize;
            cSize += compressChunk(ress, src, readSize, 0, ress->dstBuffer + cSize, bs, fi.blockIndependent, fi.blockChecksum);
            writeLE32(ress->dstBuffer + cSize, 0); cSize += 4;
            if (fi.contentChecksum) { writeLE32(ress->dstBuffer + cSize, xxh32(src, readSize, 0)); cSize += 4; }
            compressedfilesize = cSize;
            DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   \r", (unsigned)(filesize >> 20), (double)compressedfilesize / (double)(filesize + !filesize) * 100);
            if (fwrite(ress->dstBuffer, 1, cSize, foutput) != cSize) EXM_THROW(42, "Write error : failed writing single-block compressed frame");
        } else {
            size_t prevTail = 0;  /* amount of previous data kept before src (up to 64 KB) */
            int firstUpdate = 1;
            headerSize = writeFrameHeader(header, &fi);
            if (fwrite(header, 1, headerSize, foutput) != headerSize) EXM_THROW(37, "Write error : cannot write header");
            compressedfilesize += headerSize;
            while (readSize > 0) {
                size_t cSize;
                if (firstUpdate) {
                    DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   \r", 0u, (double)compressedfilesize / 0.0 * 100);
                    firstUpdate = 0;
                }
                if (fi.contentChecksum) xxh32_update(&xxh, src, readSize);
                cSize = compressChunk(ress, src, readSize, (int)prevTail, ress->dstBuffer, blockSize, fi.blockIndependent, fi.blockChecksum);
                compressedfilesize += cSize;
                if (fwrite(ress->dstBuffer, 1, cSize, foutput) != cSize) EXM_THROW(38, "Write error : cannot write compressed block");
                /* keep tail as dictionary for next chunk */
                prevTail = readSize < 64 KB ? readSize : 64 KB;
                memmove(src - prevTail, src + readSize - prevTail, prevTail);
                readSize = fread(src, 1, LZ4IO_CHUNKSIZE, finput);
                if (ferror(finput)) EXM_THROW(30, "Error reading %s ", srcFileName);
                if (readSize > 0) {
                    DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   \r", (unsigned)(filesize >> 20), (double)compressedfilesize / (double)filesize * 100);
                }
                filesize += readSize;
            }
            {
                uint8_t tail[8];
                size_t tailSize = 4;
                writeLE32(tail, 0);
                if (fi.contentChecksum) { writeLE32(tail + 4, xxh32_digest(&xxh)); tailSize += 4; }
                if (fwrite(tail, 1, tailSize, foutput) != tailSize) EXM_THROW(38, "Write error : cannot write end of stream");
                compressedfilesize += tailSize;
            }
        }
    }

    /* Status */
    DISPLAYLEVEL(2, "\r%79s\r", "");
    DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%%\n",
                 (unsigned long long)filesize, (unsigned long long)compressedfilesize,
                 (double)compressedfilesize / (double)(filesize + !filesize) * 100);
    ress->totalInSize += filesize;

    if (finput != stdin) fclose(finput);
    if (foutput != stdout) {
        fclose(foutput);
        if (hasStat && strcmp(dstFileName, lz4io_nullmark)) setFileStat(dstFileName, &statbuf);
    } else {
        fflush(stdout);
    }
    if (prefs->removeSrcFile && strcmp(srcFileName, lz4io_stdinmark)) {
        if (remove(srcFileName)) EXM_THROW(40, "Remove error : %s: %s", srcFileName, strerror(errno));
    }
    return 0;
}

static void displayDone(double startWall, clock_t startCpu, uint64_t totalSize, int level)
{
    double timeLength = nowSec() - startWall;
    double cpuTime = (double)(clock() - startCpu) / CLOCKS_PER_SEC;
    if (timeLength <= 0) timeLength = 1e-9;
    DISPLAYLEVEL(level, "Done in %.2f s ==> %.2f MiB/s  (cpu load : %.0f%%)\n",
                 timeLength, (double)totalSize / timeLength / 1024 / 1024, cpuTime / timeLength * 100);
}

int lz4io_compressFilename(const char* srcFileName, const char* dstFileName, const lz4io_prefs* prefs)
{
    double const startWall = nowSec();
    clock_t const startCpu = clock();
    cRess_t ress = createCResources(prefs);
    int const result = compressFilename_extRess(&ress, srcFileName, dstFileName, prefs);
    displayDone(startWall, startCpu, ress.totalInSize, 3);
    freeCResources(&ress);
    return result;
}

int lz4io_compressMultipleFilenames(const char** inFileNames, int ifntSize, const char* suffix, const lz4io_prefs* prefs)
{
    int i;
    int missed_files = 0;
    char* dstFileName = (char*)malloc_or_die(4096);
    size_t ofnSize = 4096;
    const size_t suffixSize = strlen(suffix);
    double const startWall = nowSec();
    clock_t const startCpu = clock();
    cRess_t ress = createCResources(prefs);

    for (i = 0; i < ifntSize; i++) {
        size_t const ifnSize = strlen(inFileNames[i]);
        if (!strcmp(suffix, lz4io_stdoutmark)) {
            missed_files += compressFilename_extRess(&ress, inFileNames[i], lz4io_stdoutmark, prefs);
            continue;
        }
        if (ofnSize <= ifnSize + suffixSize + 1) { free(dstFileName); ofnSize = ifnSize + 20; dstFileName = (char*)malloc_or_die(ofnSize); }
        strcpy(dstFileName, inFileNames[i]);
        strcat(dstFileName, suffix);
        missed_files += compressFilename_extRess(&ress, inFileNames[i], dstFileName, prefs);
    }
    displayDone(startWall, startCpu, ress.totalInSize, 3);
    freeCResources(&ress);
    free(dstFileName);
    return missed_files;
}

/* ============================================================
 *                      Decompression
 * ============================================================ */

typedef struct {
    uint8_t* srcBuffer;
    size_t srcBufferSize;
    uint8_t* dstBuffer;     /* 64 KB history + block */
    size_t dstBufferSize;
    uint8_t* dictBuffer;
    size_t dictBufferSize;
    FILE* dstFile;
    int sparse;
    unsigned storedSkips;
} dRess_t;

static dRess_t createDResources(const lz4io_prefs* prefs)
{
    dRess_t r;
    memset(&r, 0, sizeof(r));
    r.srcBufferSize = 64 KB;
    r.srcBuffer = (uint8_t*)malloc_or_die(r.srcBufferSize);
    r.dstBufferSize = 64 KB + 4 MB + 8;
    r.dstBuffer = (uint8_t*)malloc_or_die(r.dstBufferSize);
    if (prefs->dictionaryFilename) {
        FILE* f = openSrcFile(prefs->dictionaryFilename);
        uint8_t* buf;
        size_t used = 0;
        if (f == NULL) EXM_THROW(27, "Dictionary error : could not open dictionary file");
        buf = (uint8_t*)malloc_or_die(2 * (64 KB));
        for (;;) {
            size_t rd = fread(buf + used, 1, 64 KB, f);
            used += rd;
            if (used > 64 KB) { memmove(buf, buf + used - 64 KB, 64 KB); used = 64 KB; }
            if (rd == 0) break;
        }
        if (f != stdin) fclose(f);
        r.dictBuffer = buf;
        r.dictBufferSize = used;
    }
    return r;
}

static void freeDResources(dRess_t* r) { free(r->srcBuffer); free(r->dstBuffer); free(r->dictBuffer); }

/* sparse-aware writing */
static unsigned fwriteSparse(FILE* file, const void* buffer, size_t bufferSize, int sparseEnabled, unsigned storedSkips)
{
    const size_t sizeT = sizeof(size_t);
    const size_t maskT = sizeT - 1;
    const size_t* const bufferT = (const size_t*)buffer;
    const size_t* ptrT = bufferT;
    size_t bufferSizeT = bufferSize / sizeT;
    const size_t* const bufferTEnd = bufferT + bufferSizeT;
    const size_t segmentSizeT = (32 KB) / sizeT;

    if (!sparseEnabled) {
        size_t const sizeCheck = fwrite(buffer, 1, bufferSize, file);
        if (sizeCheck != bufferSize) EXM_THROW(70, "Write error : cannot write decoded block");
        return 0;
    }
    /* avoid int overflow */
    if (storedSkips > 1 GB) {
        int const seekResult = fseek(file, 1 GB, SEEK_CUR);
        if (seekResult != 0) EXM_THROW(71, "1 GB skip error (sparse file support)");
        storedSkips -= 1 GB;
    }
    while (ptrT < bufferTEnd) {
        size_t seg0SizeT = segmentSizeT;
        const size_t* ptrStart = ptrT;
        size_t nb0T;
        if (bufferTEnd - ptrT < (ptrdiff_t)seg0SizeT) seg0SizeT = (size_t)(bufferTEnd - ptrT);
        {
            const size_t* const ptrEnd = ptrT + seg0SizeT;
            while ((ptrT < ptrEnd) && (*ptrT == 0)) ptrT++;
        }
        nb0T = (size_t)(ptrT - ptrStart);
        storedSkips += (unsigned)(nb0T * sizeT);
        if (ptrT == bufferTEnd) break;
        {
            const size_t* ptrEnd = ptrT + seg0SizeT - nb0T;
            size_t nonZeroT;
            /* find end of the non-zero run within segment */
            const size_t* p2 = ptrT;
            if (ptrEnd > bufferTEnd) ptrEnd = bufferTEnd;
            while (p2 < ptrEnd && *p2 != 0) p2++;
            /* actually write up to segment end like reference behaviour: write whole remaining segment */
            nonZeroT = (size_t)(ptrEnd - ptrT);
            (void)p2;
            if (storedSkips > 0) {
                int const seekResult = fseek(file, storedSkips, SEEK_CUR);
                if (seekResult) EXM_THROW(72, "Sparse skip error ; try --no-sparse");
                storedSkips = 0;
            }
            {
                size_t const sizeCheck = fwrite(ptrT, sizeT, nonZeroT, file);
                if (sizeCheck != nonZeroT) EXM_THROW(73, "Write error : cannot write decoded block");
            }
            ptrT += nonZeroT;
        }
    }
    {
        size_t const restSize = bufferSize & maskT;
        if (restSize) {
            const char* const restStart = (const char*)bufferTEnd;
            const char* restPtr = restStart;
            const char* const restEnd = restStart + restSize;
            while ((restPtr < restEnd) && (*restPtr == 0)) restPtr++;
            storedSkips += (unsigned)(restPtr - restStart);
            if (restPtr != restEnd) {
                if (storedSkips > 0) {
                    int const seekResult = fseek(file, storedSkips, SEEK_CUR);
                    if (seekResult) EXM_THROW(74, "Sparse skip error ; try --no-sparse");
                    storedSkips = 0;
                }
                {
                    size_t const sizeCheck = fwrite(restPtr, 1, (size_t)(restEnd - restPtr), file);
                    if (sizeCheck != (size_t)(restEnd - restPtr)) EXM_THROW(75, "Write error : cannot write decoded end of block");
                }
            }
        }
    }
    return storedSkips;
}

static void fwriteSparseEnd(FILE* file, unsigned storedSkips)
{
    if (storedSkips > 0) {
        const char lastZeroByte[1] = { 0 };
        if (fseek(file, storedSkips - 1, SEEK_CUR) != 0) EXM_THROW(69, "Final skip error (sparse file)\n");
        if (fwrite(lastZeroByte, 1, 1, file) != 1) EXM_THROW(69, "Write error : cannot write last zero\n");
    }
}

static void dWrite(dRess_t* r, const void* data, size_t size, int testMode)
{
    if (testMode) return;
    r->storedSkips = fwriteSparse(r->dstFile, data, size, r->sparse, r->storedSkips);
}

/* ---------- legacy decoding ---------- */
static uint64_t decodeLegacyStream(dRess_t* r, FILE* finput, int testMode, int* undecodable)
{
    uint64_t streamSize = 0;
    uint8_t* in_buff = (uint8_t*)malloc_or_die(compressBound(LEGACY_BLOCKSIZE));
    uint8_t* out_buff = (uint8_t*)malloc_or_die(LEGACY_BLOCKSIZE);
    *undecodable = 0;
    for (;;) {
        uint8_t sizeBuf[4];
        size_t sizeCheck;
        uint32_t blockSize;
        int decodeSize;
        sizeCheck = fread(sizeBuf, 1, 4, finput);
        if (sizeCheck == 0) break;
        if (sizeCheck != 4) EXM_THROW(61, "Error: cannot read block size in Legacy format");
        blockSize = readLE32(sizeBuf);
        if (blockSize > compressBound(LEGACY_BLOCKSIZE)) {
            /* probably the beginning of a new frame: push back the 4 bytes */
            if (fseek(finput, -4, SEEK_CUR) != 0) {
                /* cannot seek (pipe): remember the bytes */
                *undecodable = 1;
                memcpy(r->srcBuffer, sizeBuf, 4);
                *undecodable = 2;
            }
            break;
        }
        sizeCheck = fread(in_buff, 1, blockSize, finput);
        if (sizeCheck != blockSize) EXM_THROW(63, "Read error : cannot access compressed block !");
        decodeSize = lz4b_decompress_safe(in_buff, out_buff, (int)blockSize, (int)LEGACY_BLOCKSIZE);
        if (decodeSize < 0) EXM_THROW(64, "Decoding Failed ! Corrupted input detected !");
        streamSize += (uint64_t)decodeSize;
        dWrite(r, out_buff, (size_t)decodeSize, testMode);
        DISPLAYUPDATE(2, "\rDecompressed : %u MiB  ", (unsigned)(streamSize >> 20));
    }
    if (ferror(finput)) EXM_THROW(65, "Read error : ferror on input file");
    free(in_buff); free(out_buff);
    return streamSize;
}

/* ---------- LZ4 frame decoding ---------- */
static const char* dErrorNames[] = { "ERROR_GENERIC" };
#define DERR(name) ("ERROR_" name)

/* reads exactly n bytes; returns 0 on short read */
static int readFull(FILE* f, void* dst, size_t n)
{
    size_t r = fread(dst, 1, n, f);
    return r == n;
}

static uint64_t decompressLZ4F(dRess_t* r, FILE* finput, int testMode)
{
    uint64_t filesize = 0;
    uint8_t hdr[19];
    uint8_t flg, bd;
    int version, blockIndep, blockChecksumFlag, contentSizeFlag, contentChecksumFlag, dictIdFlag;
    size_t hlen;
    int blockSizeId;
    size_t maxBlockSize;
    uint64_t contentSize = 0;
    xxh32_state xxh;
    uint8_t* const history = r->dstBuffer;             /* 64 KB of history before block output */
    uint8_t* const out = r->dstBuffer + 64 KB;
    size_t histSize = 0;                                /* valid history bytes before 'out' */
    const uint8_t* dict = r->dictBuffer;
    size_t dictSize = r->dictBufferSize;
    uint8_t* inBuf;
    size_t inCap;

    /* header: FLG + BD already needed */
    if (!readFull(finput, hdr, 2)) EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame");
    flg = hdr[0]; bd = hdr[1];
    version = flg >> 6;
    blockIndep = (flg >> 5) & 1;
    blockChecksumFlag = (flg >> 4) & 1;
    contentSizeFlag = (flg >> 3) & 1;
    contentChecksumFlag = (flg >> 2) & 1;
    dictIdFlag = flg & 1;
    hlen = 2 + (contentSizeFlag ? 8 : 0) + (dictIdFlag ? 4 : 0);
    if (!readFull(finput, hdr + 2, hlen - 2 + 1)) EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame");
    if (version != 1) EXM_THROW(34, "Decompression error : %s", "ERROR_headerVersion_wrong");
    if (flg & 0x02) EXM_THROW(34, "Decompression error : %s", "ERROR_reservedFlag_set");
    if (bd & 0x8F) EXM_THROW(34, "Decompression error : %s", "ERROR_reservedFlag_set");
    blockSizeId = (bd >> 4) & 7;
    if (blockSizeId < 4) EXM_THROW(34, "Decompression error : %s", "ERROR_maxBlockSize_invalid");
    maxBlockSize = (size_t)blockSizeFromId(blockSizeId);
    if (contentSizeFlag) contentSize = readLE64(hdr + 2);
    {
        uint8_t const hc = (uint8_t)((xxh32(hdr, hlen, 0) >> 8) & 0xFF);
        if (hc != hdr[hlen]) EXM_THROW(34, "Decompression error : %s", "ERROR_headerChecksum_invalid");
    }
    (void)contentSize;
    xxh32_reset(&xxh, 0);
    inCap = compressBound(maxBlockSize) + 8;
    inBuf = (uint8_t*)malloc_or_die(inCap);

    for (;;) {
        uint8_t bh[4];
        uint32_t bsize;
        int uncompressed;
        size_t decoded;
        if (!readFull(finput, bh, 4)) { free(inBuf); EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame"); }
        bsize = readLE32(bh);
        if (bsize == 0) break;
        uncompressed = (bsize >> 31) != 0;
        bsize &= 0x7FFFFFFF;
        if (bsize > maxBlockSize) { free(inBuf); EXM_THROW(34, "Decompression error : %s", "ERROR_maxBlockSize_invalid"); }
        if (!readFull(finput, inBuf, bsize)) { free(inBuf); EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame"); }
        if (blockChecksumFlag) {
            uint8_t cs[4];
            if (!readFull(finput, cs, 4)) { free(inBuf); EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame"); }
            if (readLE32(cs) != xxh32(inBuf, bsize, 0)) { free(inBuf); EXM_THROW(34, "Decompression error : %s", "ERROR_blockChecksum_invalid"); }
        }
        if (uncompressed) {
            memcpy(out, inBuf, bsize);
            decoded = bsize;
        } else {
            int res;
            if (histSize > 0) {
                /* history is contiguous before 'out' */
                res = lz4b_decompress_safe_usingDict(inBuf, out, (int)bsize, (int)maxBlockSize, out - histSize, (int)histSize);
            } else if (dict && dictSize > 0) {
                res = lz4b_decompress_safe_usingDict(inBuf, out, (int)bsize, (int)maxBlockSize, dict, (int)dictSize);
            } else {
                res = lz4b_decompress_safe(inBuf, out, (int)bsize, (int)maxBlockSize);
            }
            if (res < 0) { free(inBuf); EXM_THROW(34, "Decompression error : %s", "ERROR_decompressionFailed"); }
            decoded = (size_t)res;
        }
        if (contentChecksumFlag) xxh32_update(&xxh, out, decoded);
        dWrite(r, out, decoded, testMode);
        filesize += decoded;
        DISPLAYUPDATE(2, "\rDecompressed : %u MiB  ", (unsigned)(filesize >> 20));
        if (!blockIndep) {
            /* maintain 64 KB history before out */
            if (decoded >= 64 KB) {
                memcpy(history, out + decoded - 64 KB, 64 KB);
                histSize = 64 KB;
            } else {
                size_t keepOld = histSize + decoded > 64 KB ? 64 KB - decoded : histSize;
                if (histSize == 0 && dict && dictSize > 0) {
                    /* first block: dictionary becomes history */
                    size_t dk = dictSize > 64 KB - decoded ? 64 KB - decoded : dictSize;
                    memmove(history + 64 KB - decoded - dk, dict + dictSize - dk, dk);
                    memcpy(history + 64 KB - decoded, out, decoded);
                    histSize = dk + decoded;
                } else {
                    memmove(history + 64 KB - decoded - keepOld, out - keepOld, keepOld);
                    memcpy(history + 64 KB - decoded, out, decoded);
                    histSize = keepOld + decoded;
                }
            }
            /* history now ends exactly at 'out' (history + 64KB) */
        } else {
            histSize = 0;
        }
    }
    if (contentChecksumFlag) {
        uint8_t cs[4];
        if (!readFull(finput, cs, 4)) { free(inBuf); EXM_THROW(26, "LZ4F frame decoding could not complete: invalid frame"); }
        if (readLE32(cs) != xxh32_digest(&xxh)) { free(inBuf); EXM_THROW(34, "Decompression error : %s", "ERROR_contentChecksum_invalid"); }
    }
    if (contentSizeFlag && contentSize != filesize) { free(inBuf); EXM_THROW(34, "Decompression error : %s", "ERROR_frameSize_wrong"); }
    free(inBuf);
    (void)dErrorNames;
    return filesize;
}

static uint64_t passThrough(dRess_t* r, FILE* finput, const uint8_t* magic4, int testMode)
{
    uint64_t total = 4;
    uint8_t buf[64 KB];
    dWrite(r, magic4, 4, testMode);
    for (;;) {
        size_t n = fread(buf, 1, sizeof(buf), finput);
        if (n == 0) break;
        dWrite(r, buf, n, testMode);
        total += n;
    }
    return total;
}

/* returns 0 on success, 1 if trailing undecodable data */
static uint64_t decodeFrames(dRess_t* r, FILE* finput, const lz4io_prefs* prefs, int* status)
{
    uint64_t filesize = 0;
    unsigned nbFrames = 0;
    uint8_t MNstore[4];
    int pending = 0;   /* MNstore holds already-read bytes (from legacy push-back on non-seekable input) */
    *status = 0;
    for (;;) {
        uint32_t magicNumber;
        size_t nbReadBytes;
        if (pending) { nbReadBytes = 4; pending = 0; }
        else nbReadBytes = fread(MNstore, 1, 4, finput);
        if (nbReadBytes == 0) break;
        if (nbReadBytes != 4) EXM_THROW(40, "Unrecognized header : Magic Number unreadable");
        magicNumber = readLE32(MNstore);
        if ((magicNumber & LZ4IO_SKIPPABLEMASK) == LZ4IO_SKIPPABLE0) magicNumber = LZ4IO_SKIPPABLE0;
        switch (magicNumber) {
        case LZ4IO_MAGICNUMBER:
            filesize += decompressLZ4F(r, finput, prefs->testMode);
            break;
        case LEGACY_MAGICNUMBER:
            DISPLAYLEVEL(4, "Detected : Legacy format \n");
            {
                int und = 0;
                filesize += decodeLegacyStream(r, finput, prefs->testMode, &und);
                if (und == 2) pending = 1;
            }
            break;
        case LZ4IO_SKIPPABLE0:
            DISPLAYLEVEL(4, "Skipping detected skippable area \n");
            {
                uint8_t sz[4];
                if (fread(sz, 1, 4, finput) != 4) EXM_THROW(42, "Stream error : skippable size unreadable");
                {
                    uint32_t const size = readLE32(sz);
                    if (fseek(finput, (long)size, SEEK_CUR) != 0) {
                        /* non seekable: read through */
                        uint8_t tmp[4096];
                        uint32_t remaining = size;
                        while (remaining) {
                            size_t want = remaining > sizeof(tmp) ? sizeof(tmp) : remaining;
                            size_t got = fread(tmp, 1, want, finput);
                            if (got == 0) EXM_THROW(43, "Stream error : cannot skip skippable area");
                            remaining -= (uint32_t)got;
                        }
                    }
                }
            }
            break;
        default:
            if (nbFrames == 0) {
                if (!prefs->testMode && prefs->overwrite && prefs->passThrough) {
                    filesize += passThrough(r, finput, MNstore, prefs->testMode);
                    nbFrames = 1;
                    goto done;
                }
                EXM_THROW(44, "Unrecognized header : file cannot be decoded");
            }
            {
                long int const position = ftell(finput);
                DISPLAYLEVEL(2, "Stream followed by undecodable data ");
                if (position != -1L) DISPLAYLEVEL(2, "at position %i ", (int)position);
                DISPLAYLEVEL(2, "\n");
                *status = 1;
            }
            goto done;
        }
        nbFrames++;
    }
done:
    return filesize;
}

static int decompressSrcFile(dRess_t* r, const char* input_filename, const char* output_filename, const lz4io_prefs* prefs)
{
    FILE* const foutput = openDstFile(output_filename, prefs);
    FILE* finput;
    uint64_t filesize;
    int status = 0;
    struct stat statbuf;
    int hasStat = 0;
    if (foutput == NULL) return 1;
    finput = openSrcFile(input_filename);
    if (finput == NULL) { if (foutput != stdout) fclose(foutput); return 1; }
    if (strcmp(input_filename, lz4io_stdinmark) && stat(input_filename, &statbuf) == 0) hasStat = 1;

    r->dstFile = foutput;
    r->storedSkips = 0;
    r->sparse = prefs->sparseFileSupport;
    if (foutput == stdout && prefs->sparseFileSupport == 1) r->sparse = 0;
    if (!strcmp(output_filename, lz4io_nullmark)) r->sparse = 0;

    filesize = decodeFrames(r, finput, prefs, &status);
    if (!prefs->testMode) fwriteSparseEnd(foutput, r->storedSkips);

    DISPLAYLEVEL(2, "\r%79s\r", "");
    DISPLAYLEVEL(2, "%-30.30s : decoded %llu bytes \n", input_filename, (unsigned long long)filesize);

    if (finput != stdin) fclose(finput);
    if (foutput != stdout) {
        fclose(foutput);
        if (hasStat && strcmp(output_filename, lz4io_nullmark)) setFileStat(output_filename, &statbuf);
    } else fflush(stdout);
    if (prefs->removeSrcFile && strcmp(input_filename, lz4io_stdinmark)) {
        if (remove(input_filename)) EXM_THROW(45, "Remove error : %s: %s", input_filename, strerror(errno));
    }
    return status;
}

int lz4io_decompressFilename(const char* input_filename, const char* output_filename, const lz4io_prefs* prefs)
{
    dRess_t ress = createDResources(prefs);
    double const startWall = nowSec();
    clock_t const startCpu = clock();
    int const status = decompressSrcFile(&ress, input_filename, output_filename, prefs);
    if (status != 0) displayDone(startWall, startCpu, 0, 3);
    freeDResources(&ress);
    return status;
}

int lz4io_decompressMultipleFilenames(const char** inFileNames, int ifntSize, const char* suffix, const lz4io_prefs* prefs)
{
    int i;
    int skippedFiles = 0;
    int missingFiles = 0;
    char* outFileName = (char*)malloc_or_die(4096);
    size_t ofnSize = 4096;
    size_t const suffixSize = strlen(suffix);
    dRess_t ress = createDResources(prefs);
    double const startWall = nowSec();
    clock_t const startCpu = clock();

    for (i = 0; i < ifntSize; i++) {
        size_t const ifnSize = strlen(inFileNames[i]);
        const char* const suffixPtr = inFileNames[i] + ifnSize - suffixSize;
        if (!strcmp(suffix, lz4io_stdoutmark)) {
            missingFiles += decompressSrcFile(&ress, inFileNames[i], lz4io_stdoutmark, prefs);
            continue;
        }
        if (ofnSize <= ifnSize - suffixSize + 1) { free(outFileName); ofnSize = ifnSize + 20; outFileName = (char*)malloc_or_die(ofnSize); }
        if (ifnSize <= suffixSize || strcmp(suffixPtr, suffix) != 0) {
            DISPLAYLEVEL(1, "File extension doesn't match expected LZ4_EXTENSION (%4s); will not process file: %s\n", suffix, inFileNames[i]);
            skippedFiles++;
            continue;
        }
        memcpy(outFileName, inFileNames[i], ifnSize - suffixSize);
        outFileName[ifnSize - suffixSize] = '\0';
        missingFiles += decompressSrcFile(&ress, inFileNames[i], outFileName, prefs);
    }
    displayDone(startWall, startCpu, 0, 3);
    freeDResources(&ress);
    free(outFileName);
    return missingFiles + skippedFiles;
}

/* ============================================================
 *                      File information (--list)
 * ============================================================ */

typedef struct {
    uint64_t compressedSize;
    uint64_t contentSize;
    int hasContentSize;
    int blockSizeId;
    int blockIndependent;
    int contentChecksum;
    int frameType;   /* 0 lz4, 1 legacy, 2 skippable */
} frameSummary_t;

static const char* toHuman(double size, char* buf, size_t bufSize)
{
    const char units[] = { '\0', 'K', 'M', 'G', 'T', 'P', 'E' };
    int u = 0;
    while (size >= 1024.0 && u < 6) { size /= 1024.0; u++; }
    if (units[u]) snprintf(buf, bufSize, "%.2f%c", size, units[u]);
    else snprintf(buf, bufSize, "%.2f", size);
    return buf;
}

/* parse an LZ4 frame starting after the magic; returns 0 ok, <0 error. Skips over blocks. */
static int getFrameInfoLZ4F(FILE* f, frameSummary_t* fs)
{
    uint8_t hdr[19];
    uint8_t flg, bd;
    int contentSizeFlag, dictIdFlag, blockChecksumFlag;
    size_t hlen;
    size_t maxBlockSize;
    uint64_t total = 4;
    if (fread(hdr, 1, 2, f) != 2) return -1;
    flg = hdr[0]; bd = hdr[1];
    if ((flg >> 6) != 1) return -1;
    contentSizeFlag = (flg >> 3) & 1; dictIdFlag = flg & 1; blockChecksumFlag = (flg >> 4) & 1;
    hlen = 2 + (contentSizeFlag ? 8 : 0) + (dictIdFlag ? 4 : 0);
    if (fread(hdr + 2, 1, hlen - 2 + 1, f) != hlen - 2 + 1) return -1;
    if (((xxh32(hdr, hlen, 0) >> 8) & 0xFF) != hdr[hlen]) return -1;
    fs->blockSizeId = (bd >> 4) & 7;
    if (fs->blockSizeId < 4) return -1;
    maxBlockSize = (size_t)blockSizeFromId(fs->blockSizeId);
    fs->blockIndependent = (flg >> 5) & 1;
    fs->contentChecksum = (flg >> 2) & 1;
    fs->hasContentSize = contentSizeFlag;
    fs->contentSize = contentSizeFlag ? readLE64(hdr + 2) : 0;
    total += hlen + 1;
    for (;;) {
        uint8_t bh[4];
        uint32_t bsize;
        if (fread(bh, 1, 4, f) != 4) return -1;
        total += 4;
        bsize = readLE32(bh) & 0x7FFFFFFF;
        if (bsize == 0) break;
        if (bsize > maxBlockSize) return -1;
        if (fseek(f, (long)bsize + (blockChecksumFlag ? 4 : 0), SEEK_CUR) != 0) return -1;
        total += bsize + (blockChecksumFlag ? 4 : 0);
    }
    if (fs->contentChecksum) { if (fseek(f, 4, SEEK_CUR) != 0) return -1; total += 4; }
    fs->compressedSize = total;
    fs->frameType = 0;
    return 0;
}

static int getFrameInfoLegacy(FILE* f, frameSummary_t* fs)
{
    uint64_t total = 4;
    for (;;) {
        uint8_t sb[4];
        uint32_t bsize;
        size_t rd = fread(sb, 1, 4, f);
        if (rd == 0) break;
        if (rd != 4) return -1;
        bsize = readLE32(sb);
        if (bsize > compressBound(LEGACY_BLOCKSIZE)) { fseek(f, -4, SEEK_CUR); break; }
        if (fseek(f, (long)bsize, SEEK_CUR) != 0) return -1;
        total += 4 + bsize;
    }
    fs->compressedSize = total;
    fs->frameType = 1;
    return 0;
}

int lz4io_displayCompressedFilesInfo(const char** inFileNames, size_t ifnIdx)
{
    int result = 0;
    size_t idx;
    if (g_displayLevel < 3) {
        DISPLAYOUT("%10s %14s %5s %11s %13s %9s   %s\n", "Frames", "Type", "Block", "Compressed", "Uncompressed", "Ratio", "Filename");
    }
    for (idx = 0; idx < ifnIdx; idx++) {
        const char* const filename = inFileNames[idx];
        FILE* f;
        frameSummary_t* frames = NULL;
        size_t nbFrames = 0, cap = 0;
        int err = 0;
        uint64_t totalCompressed = 0, totalContent = 0;
        int allContentSize = 1;
        int eqBlockType = 1, eqBlockMode = 1, eqFrameType = 1;
        if (!strcmp(filename, lz4io_stdinmark)) {
            DISPLAYLEVEL(1, "lz4: --list does not support reading from standard input \n");
            result = 1;
            continue;
        }
        if (isDirectory(filename)) {
            DISPLAYLEVEL(1, "lz4: %s is a directory -- ignored \n", filename);
            result = 1;
            continue;
        }
        f = fopen(filename, "rb");
        if (f == NULL) {
            DISPLAYLEVEL(1, "lz4: %s: %s \n", filename, strerror(errno));
            result = 1;
            continue;
        }
        for (;;) {
            uint8_t mn[4];
            uint32_t magic;
            frameSummary_t fs;
            size_t rd = fread(mn, 1, 4, f);
            if (rd == 0) break;
            if (rd != 4) { err = 1; break; }
            memset(&fs, 0, sizeof(fs));
            magic = readLE32(mn);
            if ((magic & LZ4IO_SKIPPABLEMASK) == LZ4IO_SKIPPABLE0) {
                uint8_t sz[4];
                uint32_t size;
                if (fread(sz, 1, 4, f) != 4) { err = 1; break; }
                size = readLE32(sz);
                if (fseek(f, (long)size, SEEK_CUR) != 0) { err = 1; break; }
                fs.compressedSize = 8 + (uint64_t)size;
                fs.frameType = 2;
            } else if (magic == LZ4IO_MAGICNUMBER) {
                if (getFrameInfoLZ4F(f, &fs) != 0) { err = 1; break; }
            } else if (magic == LEGACY_MAGICNUMBER) {
                if (getFrameInfoLegacy(f, &fs) != 0) { err = 1; break; }
            } else {
                err = 1; break;
            }
            if (nbFrames == cap) { cap = cap ? cap * 2 : 16; frames = (frameSummary_t*)realloc(frames, cap * sizeof(frameSummary_t)); if (!frames) EXM_THROW(21, "Allocation error : not enough memory"); }
            frames[nbFrames++] = fs;
        }
        fclose(f);
        if (err) {
            DISPLAYLEVEL(1, "lz4: %s: File format not recognized \n", filename);
            result = 1;
            free(frames);
            continue;
        }
        /* aggregate */
        {
            size_t i;
            for (i = 0; i < nbFrames; i++) {
                totalCompressed += frames[i].compressedSize;
                if (frames[i].frameType == 0 && frames[i].hasContentSize) totalContent += frames[i].contentSize;
                else if (frames[i].frameType != 2) allContentSize = 0;
                if (frames[i].frameType == 2) allContentSize = 0;
                if (i > 0) {
                    if (frames[i].frameType != frames[0].frameType) eqFrameType = 0;
                    if (frames[i].blockSizeId != frames[0].blockSizeId) eqBlockType = 0;
                    if (frames[i].blockIndependent != frames[0].blockIndependent) eqBlockMode = 0;
                }
            }
            if (nbFrames == 0) allContentSize = 0;
        }
        if (g_displayLevel >= 3) {
            size_t i;
            DISPLAYOUT("%s(%u/%u)\n", filename, (unsigned)idx + 1, (unsigned)ifnIdx);
            DISPLAYOUT("%10s %14s %5s %8s %20s %20s %9s\n", "Frame", "Type", "Block", "Checksum", "Compressed", "Uncompressed", "Ratio");
            for (i = 0; i < nbFrames; i++) {
                frameSummary_t* fs = &frames[i];
                if (fs->frameType == 0) {
                    char blockStr[8];
                    snprintf(blockStr, sizeof(blockStr), "B%d%c", fs->blockSizeId, fs->blockIndependent ? 'I' : 'D');
                    if (fs->hasContentSize) {
                        DISPLAYOUT("%10llu %14s %5s %8s %20llu %20llu %9.2f%%\n", (unsigned long long)i + 1, "LZ4Frame", blockStr,
                                   fs->contentChecksum ? "XXH32" : "-", (unsigned long long)fs->compressedSize,
                                   (unsigned long long)fs->contentSize, (double)fs->compressedSize / (double)(fs->contentSize + !fs->contentSize) * 100);
                    } else {
                        DISPLAYOUT("%10llu %14s %5s %8s %20llu %20s %9s \n", (unsigned long long)i + 1, "LZ4Frame", blockStr,
                                   fs->contentChecksum ? "XXH32" : "-", (unsigned long long)fs->compressedSize, "-", "-");
                    }
                } else if (fs->frameType == 1) {
                    DISPLAYOUT("%10llu %14s %5s %8s %20llu %20s %9s\n", (unsigned long long)i + 1, "LegacyFrame", "-", "-", (unsigned long long)fs->compressedSize, "-", "-");
                } else {
                    DISPLAYOUT("%10llu %14s %5s %8s %20llu %20s %9s\n", (unsigned long long)i + 1, "SkippableFrame", "-", "-", (unsigned long long)fs->compressedSize, "-", "-");
                }
            }
            DISPLAYOUT("\n");
        } else {
            char cbuf[32], ubuf[32], blockStr[8];
            const char* typeStr;
            const char* bStr;
            if (nbFrames == 0) { typeStr = "-"; bStr = "-"; }
            else if (!eqFrameType) { typeStr = "-"; bStr = "-"; }
            else if (frames[0].frameType == 0) {
                typeStr = "LZ4Frame";
                if (eqBlockType && eqBlockMode) { snprintf(blockStr, sizeof(blockStr), "B%d%c", frames[0].blockSizeId, frames[0].blockIndependent ? 'I' : 'D'); bStr = blockStr; }
                else bStr = "-";
            } else if (frames[0].frameType == 1) { typeStr = "LegacyFrame"; bStr = "-"; }
            else { typeStr = "SkippableFrame"; bStr = "-"; }
            toHuman((double)totalCompressed, cbuf, sizeof(cbuf));
            if (allContentSize) {
                char rbuf[32];
                toHuman((double)totalContent, ubuf, sizeof(ubuf));
                snprintf(rbuf, sizeof(rbuf), "%.2f%%", (double)totalCompressed / (double)(totalContent + !totalContent) * 100);
                DISPLAYOUT("%10llu %14s %5s %11s %13s %9s  %s \n", (unsigned long long)nbFrames, typeStr, bStr, cbuf, ubuf, rbuf, filename);
            } else {
                DISPLAYOUT("%10llu %14s %5s %11s %13s %9s   %s\n", (unsigned long long)nbFrames, typeStr, bStr, cbuf, "-", "-", filename);
            }
        }
        free(frames);
    }
    return result;
}
