#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <dirent.h>
#include "lz4io.h"
#include "lz4hc.h"
#include "bench.h"

#define LZ4_VERSION_STRING "1.10.0"
#define WELCOME_MESSAGE "*** lz4 v" LZ4_VERSION_STRING " 64-bit multithread, by Yann Collet ***\n"
#define LZ4_NBWORKERS_MAX 200
#define LZ4CAT "lz4cat"
#define UNLZ4 "unlz4"
#define LZ4_LEGACY "lz4c"

#define DISPLAY(...) fprintf(stderr, __VA_ARGS__)
#define DISPLAYLEVEL(l, ...) do { if (g_displayLevel >= (l)) DISPLAY(__VA_ARGS__); } while (0)

static const char* exeName;

static int usage(const char* exeName_)
{
    DISPLAY("Usage : \n");
    DISPLAY("      %s [arg] [input] [output] \n", exeName_);
    DISPLAY("\n");
    DISPLAY("input   : a filename \n");
    DISPLAY("          with no FILE, or when FILE is - or %s, read standard input\n", lz4io_stdinmark);
    DISPLAY("Arguments : \n");
    DISPLAY(" -1     : fast compression (default) \n");
    DISPLAY("-%d    : slowest compression level \n", LZ4HC_CLEVEL_MAX);
    DISPLAY(" -T#    : use # threads for compression (default:0==auto) \n");
    DISPLAY(" -d     : decompression (default for %s extension)\n", LZ4_EXTENSION);
    DISPLAY(" -f     : overwrite output without prompting \n");
    DISPLAY(" -k     : preserve source files(s)  (default) \n");
    DISPLAY("--rm    : remove source file(s) after successful de/compression \n");
    DISPLAY(" -h/-H  : display help/long help and exit \n");
