}

static int usage_advanced(const char* exeName_)
{
    DISPLAY(WELCOME_MESSAGE);
    usage(exeName_);
    DISPLAY("\n");
    DISPLAY("Advanced arguments :\n");
    DISPLAY(" -V     : display Version number and exit \n");
    DISPLAY(" -v     : verbose mode \n");
    DISPLAY(" -q     : suppress warnings; specify twice to suppress errors too\n");
    DISPLAY(" -c     : force write to standard output, even if it is the console\n");
    DISPLAY(" -t     : test compressed file integrity\n");
    DISPLAY(" -m     : multiple input files (implies automatic output filenames)\n");
    DISPLAY(" -r     : operate recursively on directories (sets also -m) \n");
    DISPLAY(" -l     : compress using Legacy format (Linux kernel compression)\n");
    DISPLAY(" -z     : force compression \n");
    DISPLAY(" -D FILE: use FILE as dictionary (compression & decompression)\n");
    DISPLAY(" -B#    : cut file into blocks of size # bytes [32+] \n");
    DISPLAY("                     or predefined block size [4-7] (default: 7) \n");
    DISPLAY(" -BI    : Block Independence (default) \n");
    DISPLAY(" -BD    : Block dependency (improves compression ratio) \n");
    DISPLAY(" -BX    : enable block checksum (default:disabled) \n");
    DISPLAY("--no-frame-crc : disable stream checksum (default:enabled) \n");
    DISPLAY("--content-size : compressed frame includes original size (default:not present)\n");
    DISPLAY("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n");
    DISPLAY("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n");
    DISPLAY("--favor-decSpeed: compressed files decompress faster, but are less compressed \n");
    DISPLAY("--fast[=#]: switch to ultra fast compression level (default: %i)\n", 1);
    DISPLAY("--best  : same as -%d\n", LZ4HC_CLEVEL_MAX);
    DISPLAY("Benchmark arguments : \n");
    DISPLAY(" -b#    : benchmark file(s), using # compression level (default : 1) \n");
    DISPLAY(" -e#    : test all compression levels from -bX to # (default : 1)\n");
    DISPLAY(" -i#    : minimum evaluation time in seconds (default : 3s) \n");
    return 0;
}

static int usage_longhelp(const char* exeName_)
{
    usage_advanced(exeName_);
    DISPLAY("\n");
    DISPLAY("****************************\n");
    DISPLAY("***** Advanced comment *****\n");
    DISPLAY("****************************\n");
    DISPLAY("\n");
    DISPLAY("Which values can [output] have ? \n");
    DISPLAY("---------------------------------\n");
    DISPLAY("[output] : a filename \n");
    DISPLAY("          '%s', or '-' for standard output (pipe mode)\n", lz4io_stdoutmark);
    DISPLAY("          '%s' to discard output (test mode) \n", lz4io_nullmark);
    DISPLAY("[output] can be left empty. In this case, it receives the following value :\n");
    DISPLAY("          - if stdout is not the console, then [output] = stdout \n");
    DISPLAY("          - if stdout is console : \n");
    DISPLAY("               + for compression, output to filename%s \n", LZ4_EXTENSION);
    DISPLAY("               + for decompression, output to filename without '%s'\n", LZ4_EXTENSION);
    DISPLAY("                    > if input filename has no '%s' extension : error \n", LZ4_EXTENSION);
    DISPLAY("\n");
    DISPLAY("Compression levels : \n");
    DISPLAY("---------------------\n");
    DISPLAY("-0 ... -%d => Fast compression, all identicals\n", 1 - 1 + 0 == 0 ? 1 : 1);  /* placeholder, replaced below */
    return 0;
}

static int usage_longhelp_real(const char* exeName_)
{
    usage_advanced(exeName_);
    DISPLAY("\n");
    DISPLAY("****************************\n");
    DISPLAY("***** Advanced comment *****\n");
    DISPLAY("****************************\n");
    DISPLAY("\n");
    DISPLAY("Which values can [output] have ? \n");
    DISPLAY("---------------------------------\n");
    DISPLAY("[output] : a filename \n");
    DISPLAY("          '%s', or '-' for standard output (pipe mode)\n", lz4io_stdoutmark);
    DISPLAY("          '%s' to discard output (test mode) \n", lz4io_nullmark);
    DISPLAY("[output] can be left empty. In this case, it receives the following value :\n");
    DISPLAY("          - if stdout is not the console, then [output] = stdout \n");
    DISPLAY("          - if stdout is console : \n");
    DISPLAY("               + for compression, output to filename%s \n", LZ4_EXTENSION);
    DISPLAY("               + for decompression, output to filename without '%s'\n", LZ4_EXTENSION);
    DISPLAY("                    > if input filename has no '%s' extension : error \n", LZ4_EXTENSION);
    DISPLAY("\n");
    DISPLAY("Compression levels : \n");
    DISPLAY("---------------------\n");
    DISPLAY("-0  => Default level, identical to -1 \n");
    DISPLAY("-1  => Fast compression \n");
    DISPLAY("-2 .. -%d => High compression; higher number == more compression but slower\n", LZ4HC_CLEVEL_MAX);
    DISPLAY("--best    => Highest available compression level (-%d) \n", LZ4HC_CLEVEL_MAX);
    DISPLAY("--fast=#  => Faster compression; higher number == faster but compress less\n");
    DISPLAY("\n");
    DISPLAY("stdin, stdout and the console : \n");
    DISPLAY("--------------------------------\n");
    DISPLAY("To protect the console from binary flooding (bad argument mistake)\n");
    DISPLAY("%s will refuse to read from console, or write to console \n", exeName_);
    DISPLAY("except if '-c' command is specified, to force output to console \n");
    DISPLAY("\n");
    DISPLAY("Simple example :\n");
    DISPLAY("----------------\n");
    DISPLAY("1 : compress 'filename' fast, using default output name 'filename.lz4'\n");
    DISPLAY("          %s filename\n", exeName_);
    DISPLAY("\n");
    DISPLAY("Short arguments can be aggregated. For example :\n");
    DISPLAY("----------------------------------\n");
    DISPLAY("2 : compress 'filename' in high compression mode, overwrite output if exists\n");
    DISPLAY("          %s -9 -f filename \n", exeName_);
    DISPLAY("    is equivalent to :\n");
    DISPLAY("          %s -9f filename \n", exeName_);
    DISPLAY("\n");
    DISPLAY("%s can be used in 'pure pipe mode'. For example :\n", exeName_);
    DISPLAY("-------------------------------------\n");
    DISPLAY("3 : compress data stream from 'generator', send result to 'consumer'\n");
    DISPLAY("          generator | %s | consumer \n", exeName_);
    return 0;
}

static int badusage(const char* exeName_)
{
    DISPLAYLEVEL(1, "Incorrect parameters\n");
    if (g_displayLevel >= 1) usage(exeName_);
    exit(1);
}

static void waitEnter(void)
{
    DISPLAY("Press enter to continue...\n");
    (void)getchar();
}

static const char* lastNameFromPath(const char* path)
{
    const char* name = path;
    if (strrchr(name, '/')) name = strrchr(name, '/') + 1;
    if (strrchr(name, '\\')) name = strrchr(name, '\\') + 1;
    return name;
}

static int exeNameMatch(const char* exeName_, const char* test)
{
    return !strncmp(exeName_, test, strlen(test)) &&
        (exeName_[strlen(test)] == '\0' || exeName_[strlen(test)] == '.');
}

/* reads an unsigned number from a string pointer, advances the pointer */
static unsigned readU32FromChar(const char** stringPtr)
{
    unsigned result = 0;
    while ((**stringPtr >= '0') && (**stringPtr <= '9')) {
        unsigned const max = ((unsigned)(-1)) / 10;
        unsigned last = result;
        if (result > max) { DISPLAYLEVEL(1, "ERROR: numeric value too large \n"); exit(1); }
        result *= 10;
        result += (unsigned)(**stringPtr - '0');
        if (result < last) { DISPLAYLEVEL(1, "ERROR: numeric value too large \n"); exit(1); }
        (*stringPtr)++;
    }
    if ((**stringPtr == 'K') || (**stringPtr == 'M')) {
        unsigned const maxK = ((unsigned)(-1)) >> 10;
        if (result > maxK) { DISPLAYLEVEL(1, "ERROR: numeric value too large \n"); exit(1); }
        result <<= 10;
        if (**stringPtr == 'M') {
            if (result > maxK) { DISPLAYLEVEL(1, "ERROR: numeric value too large \n"); exit(1); }
            result <<= 10;
        }
        (*stringPtr)++;
        if (**stringPtr == 'i') (*stringPtr)++;
        if (**stringPtr == 'B') (*stringPtr)++;
    }
    return result;
}

/* checks that stringPtr starts with longCommand; advances stringPtr if so */
static int longCommandWArg(const char** stringPtr, const char* longCommand)
{
    size_t const comSize = strlen(longCommand);
    int const result = !strncmp(*stringPtr, longCommand, comSize);
    if (result) *stringPtr += comSize;
    return result;
}

typedef enum { om_auto, om_compress, om_decompress, om_test, om_bench, om_list } operationMode_e;

static operationMode_e determineOpMode(const char* inputFilename)
{
    size_t const inSize = strlen(inputFilename);
    size_t const extSize = strlen(LZ4_EXTENSION);
    size_t const extStart = (inSize > extSize) ? inSize - extSize : 0;
    if (!strcmp(inputFilename + extStart, LZ4_EXTENSION)) return om_decompress;
    else return om_compress;
}

/* ---- file list handling (for -m / -r) ---- */
typedef struct { const char** names; size_t count; size_t cap; char* pool; size_t poolUsed; size_t poolCap; } fileList_t;

static void fileListAdd(fileList_t* l, const char* name)
{
    size_t len = strlen(name) + 1;
    if (l->count == l->cap) { l->cap = l->cap ? l->cap * 2 : 64; l->names = (const char**)realloc(l->names, l->cap * sizeof(char*)); if (!l->names) exit(1); }
    l->names[l->count++] = strdup(name);
}

static void listFilesRecursive(fileList_t* l, const char* dirName)
{
    DIR* dir = opendir(dirName);
    struct dirent* entry;
    if (dir == NULL) {
        DISPLAYLEVEL(1, "Cannot open directory '%s': %s\n", dirName, strerror(errno));
        return;
    }
    while ((entry = readdir(dir)) != NULL) {
        char* path;
        size_t dirLen = strlen(dirName);
        struct stat st;
        if (strcmp(entry->d_name, "..") == 0 || strcmp(entry->d_name, ".") == 0) continue;
        path = (char*)malloc(dirLen + strlen(entry->d_name) + 2);
        if (!path) exit(1);
        strcpy(path, dirName);
        if (dirLen > 0 && dirName[dirLen - 1] != '/') strcat(path, "/");
        strcat(path, entry->d_name);
        if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) listFilesRecursive(l, path);
        else if (stat(path, &st) == 0 && S_ISREG(st.st_mode)) fileListAdd(l, path);
        free(path);
    }
    closedir(dir);
}

static int defaultNbWorkers(void)
{
    long n = sysconf(_SC_NPROCESSORS_ONLN);
    int nbCores = (n > 0) ? (int)n : 1;
    int spared = 1 + (nbCores >> 3);
    if (nbCores <= spared) return 1;
    return nbCores - spared;
}

int main(int argc, const char** argv)
{
    int i;
    int cLevel = 1;
    int cLevelLast = -10000;
    int legacy_format = 0;
    int forceStdout = 0;
    int forceOverwrite = 0;
    int main_pause = 0;
    int all_arguments_are_files = 0;
    int operationResult = 0;
    operationMode_e mode = om_auto;
    const char* input_filename = NULL;
    const char* output_filename = NULL;
    const char* dictionary_filename = NULL;
    char* dynNameSpace = NULL;
    fileList_t inFiles; memset(&inFiles, 0, sizeof(inFiles));
    int multiple_inputs = 0;
    int recursive = 0;
    unsigned nbWorkers = 0;
    lz4io_prefs prefs;
    const char* const extension = LZ4_EXTENSION;
    const char* stdinmark = lz4io_stdinmark;
    const char* stdoutmark = lz4io_stdoutmark;
    const char* nulmark = lz4io_nullmark;
    int benchSeparately = 0;
    unsigned nbSeconds = 3;
    unsigned benchBlockSize = 0;

    lz4io_defaultPrefs(&prefs);
    exeName = lastNameFromPath(argv[0]);
    g_programName = exeName;

    /* lz4cat predefined behavior */
    if (exeNameMatch(exeName, LZ4CAT)) {
        mode = om_decompress;
        forceStdout = 1;
        prefs.overwrite = 1;
        output_filename = stdoutmark;
        g_displayLevel = 1;
        multiple_inputs = 1;
    }
    if (exeNameMatch(exeName, UNLZ4)) { mode = om_decompress; }
    if (exeNameMatch(exeName, LZ4_LEGACY)) { g_displayLevel = 3; }

    for (i = 1; i < argc; i++) {
        const char* argument = argv[i];
        if (!argument) continue;

        if (!all_arguments_are_files) {
            /* long commands (--long-word) */
            if (argument[0] == '-' && argument[1] == '-') {
                if (!strcmp(argument, "--")) { all_arguments_are_files = 1; continue; }
                if (!strcmp(argument, "--compress")) { mode = om_compress; continue; }
                if (!strcmp(argument, "--decompress") || !strcmp(argument, "--uncompress")) { if (mode != om_bench) mode = om_decompress; continue; }
                if (!strcmp(argument, "--multiple")) { multiple_inputs = 1; continue; }
                if (!strcmp(argument, "--test")) { mode = om_test; continue; }
                if (!strcmp(argument, "--force")) { prefs.overwrite = 1; forceOverwrite = 1; continue; }
                if (!strcmp(argument, "--no-force")) { prefs.overwrite = 0; forceOverwrite = 0; continue; }
                if (!strcmp(argument, "--stdout") || !strcmp(argument, "--to-stdout")) { forceStdout = 1; output_filename = stdoutmark; continue; }
                if (!strcmp(argument, "--frame-crc")) { prefs.streamChecksum = 1; continue; }
                if (!strcmp(argument, "--no-frame-crc")) { prefs.streamChecksum = 0; continue; }
                if (!strcmp(argument, "--no-crc")) { prefs.streamChecksum = 0; prefs.blockChecksum = 0; continue; }
                if (!strcmp(argument, "--content-size")) { prefs.contentSizeFlag = 1; continue; }
                if (!strcmp(argument, "--no-content-size")) { prefs.contentSizeFlag = 0; continue; }
                if (!strcmp(argument, "--list")) { mode = om_list; continue; }
                if (!strcmp(argument, "--sparse")) { prefs.sparseFileSupport = 2; continue; }
                if (!strcmp(argument, "--no-sparse")) { prefs.sparseFileSupport = 0; continue; }
                if (!strcmp(argument, "--favor-decSpeed")) { prefs.favorDecSpeed = 1; continue; }
                if (!strcmp(argument, "--verbose")) { g_displayLevel++; continue; }
                if (!strcmp(argument, "--quiet")) { if (g_displayLevel) g_displayLevel--; continue; }
                if (!strcmp(argument, "--version")) { DISPLAY(WELCOME_MESSAGE); return 0; }
                if (!strcmp(argument, "--help")) { usage_advanced(exeName); goto _cleanup; }
                if (!strcmp(argument, "--keep")) { prefs.removeSrcFile = 0; continue; }
                if (!strcmp(argument, "--rm")) { prefs.removeSrcFile = 1; continue; }
                if (longCommandWArg(&argument, "--threads")) {
                    if (*argument == '=') { argument++; nbWorkers = readU32FromChar(&argument); continue; }
                    badusage(exeName);
                }
                if (longCommandWArg(&argument, "--fast")) {
                    if (argument[0] == '=') {
                        unsigned fastLevel;
                        ++argument;
                        fastLevel = readU32FromChar(&argument);
                        if (fastLevel) {
                            cLevel = -(int)fastLevel;
                        } else {
                            badusage(exeName);
                        }
                    } else if (argument[0] != 0) {
                        badusage(exeName);
                    } else {
                        cLevel = -1;
                    }
                    continue;
                }
                if (longCommandWArg(&argument, "--best")) { cLevel = LZ4HC_CLEVEL_MAX; continue; }
                badusage(exeName);
            }

            /* short commands (-x) */
            if (argument[0] == '-') {
                /* '-' means stdin/stdout */
                if (argument[1] == 0) {
                    if (!input_filename) input_filename = stdinmark;
                    else output_filename = stdoutmark;
                    continue;
                }
                argument++;
                while (argument[0] != 0) {
                    /* Compression level */
                    if ((*argument >= '0') && (*argument <= '9')) {
                        cLevel = (int)readU32FromChar(&argument);
                        continue;
                    }
                    switch (argument[0]) {
                    case 'V': DISPLAY(WELCOME_MESSAGE); goto _cleanup;
                    case 'h': usage_advanced(exeName); goto _cleanup;
                    case 'H': usage_longhelp_real(exeName); goto _cleanup;
                    case 'e': argument++; cLevelLast = (int)readU32FromChar(&argument); argument--; break;
                    case 'z': mode = om_compress; break;
                    case 'D':
                        if (argument[1] == '\0') {
                            /* path is next argument */
                            if (i + 1 == argc) {
                                DISPLAYLEVEL(1, "Dictionary filename is missing \n");
                                badusage(exeName);
                            }
                            dictionary_filename = argv[++i];
                        } else {
                            dictionary_filename = argument + 1;
                        }
                        argument += strlen(argument) - 1;
                        break;
                    case 'l': legacy_format = 1; prefs.blockSize = 8 << 20; break;
                    case 'd': mode = om_decompress; break;
                    case 'c': forceStdout = 1; output_filename = stdoutmark; break;
                    case 't': mode = om_test; break;
                    case 'f': prefs.overwrite = 1; forceOverwrite = 1; break;
                    case 'v': g_displayLevel++; break;
                    case 'q': if (g_displayLevel) g_displayLevel--; break;
                    case 'k': prefs.removeSrcFile = 0; break;
                    case 'T': argument++; nbWorkers = readU32FromChar(&argument); argument--; break;
                    case 'B':
                        while (argument[1] != 0) {
                            int exitBlockProperties = 0;
                            switch (argument[1]) {
                            case 'D': prefs.blockIndependence = 0; argument++; break;
                            case 'I': prefs.blockIndependence = 1; argument++; break;
                            case 'X': prefs.blockChecksum = 1; argument++; break;
                            default:
                                if (argument[1] < '0' || argument[1] > '9') {
                                    exitBlockProperties = 1;
                                    break;
                                } else {
                                    unsigned B;
                                    argument++;
                                    B = readU32FromChar(&argument);
                                    argument--;
                                    if (B < 4) badusage(exeName);
                                    if (B <= 7) {
                                        int const bs = lz4io_setBlockSizeID(&prefs, B);
                                        benchBlockSize = (unsigned)bs;
                                        DISPLAYLEVEL(2, "using blocks of size %u KB \n", (unsigned)(bs >> 10));
                                    } else {
                                        if (B < 32) badusage(exeName);
                                        lz4io_setBlockSize(&prefs, B);
                                        benchBlockSize = B;
                                        if (B >= 1024) {
                                            DISPLAYLEVEL(2, "using blocks of size %u KB \n", (unsigned)(B >> 10));
                                        } else {
                                            DISPLAYLEVEL(2, "using blocks of size %u bytes \n", (unsigned)B);
                                        }
                                    }
                                    break;
                                }
                            }
                            if (exitBlockProperties) break;
                        }
                        break;
                    case 'b': mode = om_bench; multiple_inputs = 1; break;
                    case 'S': benchSeparately = 1; break;
                    case 'm': multiple_inputs = 1; break;
                    case 'r': recursive = 1; multiple_inputs = 1; break;
                    case 'i': argument++; nbSeconds = readU32FromChar(&argument); argument--; break;
                    case 'p': main_pause = 1; break;
                    default: badusage(exeName);
                    }
                    argument++;
                }
                continue;
            }
        }

        /* Store in *inFileNames[] if -m is used */
        if (multiple_inputs) { fileListAdd(&inFiles, argument); continue; }

        /* Store first non-option arg in input_filename to preserve original cli logic */
        if (!input_filename) { input_filename = argument; continue; }

        /* Second non-option arg in output_filename to preserve original cli logic */
        if (!output_filename) {
            output_filename = argument;
            if (!strcmp(output_filename, nulmark)) output_filename = "/dev/null";
            continue;
        }

        /* 3rd non-option arg should not exist */
        DISPLAYLEVEL(1, "%s : %s won't be used ! Do you want multiple input files (-m) ? \n", "Error", argument);
        badusage(exeName);
    }

    DISPLAYLEVEL(3, WELCOME_MESSAGE);
    DISPLAYLEVEL(4, "_POSIX_C_SOURCE defined: %ldL\n", (long)200809L);
    DISPLAYLEVEL(4, "_POSIX_VERSION defined: %ldL\n", (long)200809L);
    DISPLAYLEVEL(4, "PLATFORM_POSIX_VERSION defined: %ldL\n", (long)200809L);

    if (mode != om_decompress && mode != om_test && mode != om_list) {
        if (nbWorkers == 0) nbWorkers = (unsigned)defaultNbWorkers();
        if (nbWorkers > LZ4_NBWORKERS_MAX) {
            DISPLAYLEVEL(3, "Requested %u threads too large => automatically reduced to %u \n", nbWorkers, LZ4_NBWORKERS_MAX);
            nbWorkers = LZ4_NBWORKERS_MAX;
        } else {
            if (nbWorkers > 1) DISPLAYLEVEL(3, "Using %u threads for compression \n", nbWorkers);
        }
    }
    prefs.nbWorkers = (int)nbWorkers;

    if (recursive) {
        fileList_t expanded; memset(&expanded, 0, sizeof(expanded));
        size_t n;
        for (n = 0; n < inFiles.count; n++) {
            if (!strcmp(inFiles.names[n], stdinmark)) { fileListAdd(&expanded, inFiles.names[n]); continue; }
            {
                struct stat st;
                if (stat(inFiles.names[n], &st) == 0 && S_ISDIR(st.st_mode)) listFilesRecursive(&expanded, inFiles.names[n]);
                else fileListAdd(&expanded, inFiles.names[n]);
            }
        }
        inFiles = expanded;
    }

    if (dictionary_filename) {
        if (!strcmp(dictionary_filename, stdinmark) && !strcmp(input_filename ? input_filename : "", stdinmark)) {
            DISPLAYLEVEL(1, "refusing to read from a console\n");
            exit(1);
        }
        prefs.dictionaryFilename = dictionary_filename;
    }

    /* benchmark and test modes */
    if (mode == om_bench) {
        BMK_setNotificationLevel(g_displayLevel);
        BMK_setNbSeconds(nbSeconds);
        BMK_setBlockSize(benchBlockSize);
        BMK_setDictionary(dictionary_filename);
        if (benchSeparately) operationResult = BMK_benchFilesSeparately(inFiles.names, (unsigned)inFiles.count, cLevel, cLevelLast);
        else operationResult = BMK_benchFiles(inFiles.names, (unsigned)inFiles.count, cLevel, cLevelLast);
        goto _cleanup;
    }

    if (mode == om_test) {
        prefs.testMode = 1;
        output_filename = nulmark;
        mode = om_decompress;
    }

    if (mode == om_list) {
        if (!multiple_inputs) {
            if (input_filename) fileListAdd(&inFiles, input_filename);
            if (output_filename) fileListAdd(&inFiles, output_filename);
        }
        if (inFiles.count == 0) fileListAdd(&inFiles, stdinmark);
        operationResult = lz4io_displayCompressedFilesInfo(inFiles.names, inFiles.count);
        goto _cleanup;
    }

    /* compress or decompress */
    if (!input_filename) input_filename = stdinmark;

    /* Check if input is defined as console; trigger an error in this case */
    if (!strcmp(input_filename, stdinmark) && isatty(STDIN_FILENO) && !forceStdout) {
        DISPLAYLEVEL(1, "refusing to read from a console\n");
        exit(1);
    }
    if (!strcmp(input_filename, stdinmark) && isatty(STDIN_FILENO) && forceStdout && mode != om_decompress && mode != om_test) {
        DISPLAYLEVEL(1, "refusing to read from a console\n");
        exit(1);
    }

    if (multiple_inputs && inFiles.count == 0 && !recursive) {
        /* no file provided in multiple mode: use stdin */
        if (isatty(STDIN_FILENO)) { DISPLAYLEVEL(1, "refusing to read from a console\n"); exit(1); }
        fileListAdd(&inFiles, stdinmark);
        if (!output_filename) output_filename = stdoutmark;
    }

    /* Check if benchmark is selected */
    if (mode == om_auto) {
        if (multiple_inputs) {
            /* auto-determine by first file */
            if (inFiles.count > 0) mode = determineOpMode(inFiles.names[0]);
            else mode = om_compress;
        } else {
            mode = determineOpMode(input_filename);
        }
    }

    if (mode == om_compress) {
        if (legacy_format) prefs.useLegacyFormat = 1;
    }

    /* No output filename ==> try to select one automatically (when possible) */
    while ((!output_filename) && (multiple_inputs == 0)) {
        if (!strcmp(input_filename, stdinmark)) { output_filename = stdoutmark; break; }
        if (mode == om_compress) {
            size_t const l = strlen(input_filename);
            dynNameSpace = (char*)calloc(1, l + strlen(LZ4_EXTENSION) + 1);
            if (dynNameSpace == NULL) { perror(exeName); exit(1); }
            strcpy(dynNameSpace, input_filename);
            strcat(dynNameSpace, LZ4_EXTENSION);
            output_filename = dynNameSpace;
            DISPLAYLEVEL(2, "Compressed filename will be : %s \n", output_filename);
            break;
        }
        if (mode == om_decompress) {
            size_t outl;
            size_t const inl = strlen(input_filename);
            dynNameSpace = (char*)calloc(1, inl + 1);
            if (dynNameSpace == NULL) { perror(exeName); exit(1); }
            strcpy(dynNameSpace, input_filename);
            outl = inl;
            if (inl > 4)
                while ((outl >= inl - 4) && (input_filename[outl] == extension[outl - inl + 4])) dynNameSpace[outl--] = 0;
            if (outl != inl - 5) { DISPLAYLEVEL(1, "Cannot determine an output filename \n"); badusage(exeName); }
            output_filename = dynNameSpace;
            DISPLAYLEVEL(2, "Decoding file %s \n", output_filename);
        }
        break;
    }

    if (!output_filename) output_filename = "*\\dummy^!//";

    /* Check if output is defined as console; trigger an error in this case */
    if (!strcmp(output_filename, stdoutmark) && isatty(STDOUT_FILENO) && !forceStdout) {
        DISPLAYLEVEL(1, "refusing to write to console without -c \n");
        exit(1);
    }
    /* Downgrade notification level in stdout and multiple file mode */
    if (!strcmp(output_filename, stdoutmark) && (g_displayLevel == 2)) g_displayLevel = 1;
    if ((multiple_inputs) && (g_displayLevel == 2)) g_displayLevel = 1;

    /* Auto-determine compression or decompression, based on file extension */
    if (mode == om_decompress) {
        if (!strcmp(output_filename, stdoutmark) && !strcmp(input_filename, stdinmark) && 0) { }
        prefs.passThrough = forceOverwrite;   /* -f on decompression enables pass-through of non-lz4 data */
        if (multiple_inputs) {
            const char* dstSuffix = (!strcmp(output_filename, stdoutmark) || prefs.testMode) ? stdoutmark : LZ4_EXTENSION;
            if (prefs.testMode) dstSuffix = stdoutmark;
            operationResult = lz4io_decompressMultipleFilenames(inFiles.names, (int)inFiles.count, dstSuffix, &prefs);
        } else {
            operationResult = lz4io_decompressFilename(input_filename, output_filename, &prefs);
        }
    } else {
        /* compression */
        prefs.compressionLevel = cLevel;
        if (multiple_inputs) {
            const char* dstSuffix = (!strcmp(output_filename, stdoutmark)) ? stdoutmark : LZ4_EXTENSION;
            operationResult = lz4io_compressMultipleFilenames(inFiles.names, (int)inFiles.count, dstSuffix, &prefs);
        } else {
            operationResult = lz4io_compressFilename(input_filename, output_filename, &prefs);
        }
    }

_cleanup:
    if (main_pause) waitEnter();
    free(dynNameSpace);
    return operationResult;
}
