static int benchFileTable(const char** fileNamesTable, unsigned nbFiles, int cLevel, int cLevelLast)
{
    size_t total = 0, pos = 0;
    uint8_t* srcBuffer;
    size_t* fileSizes = (size_t*)calloc(nbFiles ? nbFiles : 1, sizeof(size_t));
