/* ---------- parallel chunk compression ---------- */
typedef struct {
    uint8_t* buf;        /* 64 KB prefix area + chunk */
    uint8_t* dst;
    size_t srcSize;
    int prefixSize;
    size_t dstSize;
    int state;           /* 0 free, 1 queued, 2 done */
} job_t;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    job_t* jobs;
    int nbJobs;
    int* queue;          /* indexes of queued jobs */
    int qHead, qCount;
    int shutdown;
    pthread_t* threads;
    int nbThreads;
    cRess_t* ress;       /* shared (cdict) */
    int blockSize, blockIndependent, blockChecksum;
} pool_t;

typedef struct { pool_t* pool; cctx_t* cctx; } workerArg_t;

static void* workerMain(void* arg)
{
    workerArg_t* wa = (workerArg_t*)arg;
    pool_t* p = wa->pool;
    for (;;) {
        int jobIdx;
        job_t* job;
        pthread_mutex_lock(&p->mutex);
        while (p->qCount == 0 && !p->shutdown) pthread_cond_wait(&p->cond, &p->mutex);
        if (p->qCount == 0 && p->shutdown) { pthread_mutex_unlock(&p->mutex); break; }
        jobIdx = p->queue[p->qHead]; p->qHead = (p->qHead + 1) % p->nbJobs; p->qCount--;
        pthread_mutex_unlock(&p->mutex);
        job = &p->jobs[jobIdx];
        {
            cRess_t local = *p->ress;
            local.cctx = wa->cctx;
            job->dstSize = compressChunk(&local, job->buf + 64 KB, job->srcSize, job->prefixSize, job->dst,
                                         p->blockSize, p->blockIndependent, p->blockChecksum);
        }
        pthread_mutex_lock(&p->mutex);
        job->state = 2;
        pthread_cond_broadcast(&p->cond);
        pthread_mutex_unlock(&p->mutex);
    }
    return NULL;
}

static void poolWaitJob(pool_t* p, int jobIdx)
{
    pthread_mutex_lock(&p->mutex);
    while (p->jobs[jobIdx].state != 2) pthread_cond_wait(&p->cond, &p->mutex);
    pthread_mutex_unlock(&p->mutex);
}

static void poolSubmit(pool_t* p, int jobIdx)
{
    pthread_mutex_lock(&p->mutex);
    p->jobs[jobIdx].state = 1;
    p->queue[(p->qHead + p->qCount) % p->nbJobs] = jobIdx;
    p->qCount++;
    pthread_cond_broadcast(&p->cond);
    pthread_mutex_unlock(&p->mutex);
}
